window.BC=window.BC||{};window.BC.meta={"CAISO": {"groups": ["COAL", "COAL_PRB", "COAL_BIT", "CC_REGULAR", "CC_CHP", "CT_PEAKER", "CT_CHP", "ST_GAS", "ST_CHP", "OTHER_FOSSIL"], "groupLabel": {"COAL": "Coal", "COAL_PRB": "Coal PRB", "COAL_BIT": "Coal Bituminous", "CC_REGULAR": "CC Regular", "CC_CHP": "CC CHP", "CT_PEAKER": "CT Peaker", "CT_CHP": "CT CHP", "ST_GAS": "Steam Gas", "ST_CHP": "Steam CHP", "OTHER_FOSSIL": "Other Fossil"}, "zones": ["NP15", "SP15", "ZP26"], "years": [2023, 2024, 2025]}, "ERCOT": {"groups": ["COAL_LIGNITE", "COAL_PRB", "CC_REGULAR", "CC_CHP", "CT_PEAKER", "CT_CHP", "ST_GAS", "ST_CHP", "OTHER_FOSSIL"], "groupLabel": {"COAL_LIGNITE": "Coal Lignite", "COAL_PRB": "Coal PRB", "CC_REGULAR": "CC Regular", "CC_CHP": "CC CHP", "CT_PEAKER": "CT Peaker", "CT_CHP": "CT CHP", "ST_GAS": "Steam Gas", "ST_CHP": "Steam CHP", "OTHER_FOSSIL": "Other Fossil"}, "zones": ["Houston", "North", "Northeast", "South", "South_Central", "West"], "years": [2023, 2024, 2025]}, "MISO": {"groups": ["COAL_LIGNITE", "COAL_PRB", "COAL_BIT", "CC_REGULAR", "CC_CHP", "CT_PEAKER", "CT_CHP", "ST_GAS", "ST_CHP", "OTHER_FOSSIL"], "groupLabel": {"COAL_LIGNITE": "Coal Lignite", "COAL_PRB": "Coal PRB", "COAL_BIT": "Coal Bituminous", "CC_REGULAR": "CC Regular", "CC_CHP": "CC CHP", "CT_PEAKER": "CT Peaker", "CT_CHP": "CT CHP", "ST_GAS": "Steam Gas", "ST_CHP": "Steam CHP", "OTHER_FOSSIL": "Other Fossil"}, "zones": ["MISO-Central", "MISO-North", "MISO-South"], "years": [2023, 2024, 2025]}, "NEISO": {"groups": ["COAL_BIT", "CC_REGULAR", "CC_CHP", "CT_PEAKER", "CT_CHP", "ST_GAS", "ST_CHP", "OTHER_FOSSIL"], "groupLabel": {"COAL_BIT": "Coal Bituminous", "CC_REGULAR": "CC Regular", "CC_CHP": "CC CHP", "CT_PEAKER": "CT Peaker", "CT_CHP": "CT CHP", "ST_GAS": "Steam Gas", "ST_CHP": "Steam CHP", "OTHER_FOSSIL": "Other Fossil"}, "zones": ["Boston", "Central", "Connecticut", "North"], "years": [2023, 2024, 2025]}, "NYISO": {"groups": ["COAL_PRB", "COAL_BIT", "CC_REGULAR", "CC_CHP", "CT_PEAKER", "CT_CHP", "ST_GAS", "ST_CHP"], "groupLabel": {"COAL_PRB": "Coal PRB", "COAL_BIT": "Coal Bituminous", "CC_REGULAR": "CC Regular", "CC_CHP": "CC CHP", "CT_PEAKER": "CT Peaker", "CT_CHP": "CT CHP", "ST_GAS": "Steam Gas", "ST_CHP": "Steam CHP"}, "zones": ["Capital_Hudson", "Long_Island", "NYC", "Upstate_West"], "years": [2023, 2024, 2025]}, "PJM": {"groups": ["COAL_PRB", "COAL_BIT", "COAL_WC", "CC_REGULAR", "CC_CHP", "CT_PEAKER", "CT_CHP", "ST_GAS", "ST_CHP", "OTHER_FOSSIL"], "groupLabel": {"COAL_PRB": "Coal PRB", "COAL_BIT": "Coal Bituminous", "COAL_WC": "Coal Waste", "CC_REGULAR": "CC Regular", "CC_CHP": "CC CHP", "CT_PEAKER": "CT Peaker", "CT_CHP": "CT CHP", "ST_GAS": "Steam Gas", "ST_CHP": "Steam CHP", "OTHER_FOSSIL": "Other Fossil"}, "zones": ["PJM_AEP_Ohio", "PJM_ATSI", "PJM_Central_PA", "PJM_ComEd", "PJM_Dominion", "PJM_EMAAC", "PJM_SWMAAC", "PJM_West_APS"], "years": [2023, 2024, 2025]}};window.BC.manifest=[{"id": "2026-06-17-neiso-17-mystic-cod", "label": "neiso 17 mystic cod", "date": "2026-06-17", "shorthand": "neiso-17-mystic-cod", "definition": "neiso 16 (ct_deploy keeper) + the within-window fleet-exit fix: whole plants that ran during the window and retired before the single recent EIA-860 operable vintage (2025ER) were absent from EVERY modeled year, so survivors over-dispatched to cover them. The textbook case is Mystic (plant 1588, ~1.4 GW Boston/NEMA CC, ~1.3 TWh in 2023, retired Jun 2024). Fix injects these exits from the final-vintage 'Retired and Canceled' sheets (cod_ramp + a backcast-only loader, mirror of planned additions) and caps each by its observed CEMS outages. Result: Mystic now dispatches 0.72 TWh 2023 / 0.85 TWh Jan-Jun 2024 in Boston, zero 2025; the modeled CC_REGULAR plant set differs by year (31/31/29, was 29 every year); total CC_REGULAR stays in tolerance (-0.2/-0.2/+8.7% vs EIA-923) and the run is gas-neutral (54.8/58.9/60.1) and level-neutral (34.5/39.8/70.5 vs DA 36.8/41.5/67.9) vs neiso 16. Mystic's 0.72 vs 1.31 actual is the reliability/RMR dispatch the economic LP cannot recover (same class as the CT/ST/oil wedge); 2025 +8.7% CC is the separate merit-order issue, untouched.", "years": [2023, 2024, 2025], "iso": "NEISO", "file": "frontend/data/backcast/runs/2026-06-17-neiso-17-mystic-cod.js"}, {"id": "2026-06-18-neiso-18-oil-agtdaily", "label": "neiso 18 oil agtdaily", "date": "2026-06-18", "shorthand": "neiso-18-oil-agtdaily", "definition": "neiso 18 (PROBE \u2014 partial pass; lever for 2025 CC over-dispatch). Baseline (neiso 17 mystic-cod) + --gas-hub-basis-daily: the daily within-month Algonquin Citygate basis shape (mean-preserving, demand-convex) with dual-fuel switched MWh re-attributed to oil. Targets the 2025 winter oil gap (Jan -330 / Dec -303 GWh in baseline). Result per-class TWh (model / EIA-923 %): CC_REGULAR 52.36 -0.0% / 56.37 -0.4% / 55.98 +5.4% (2023/24/25) vs baseline -0.2/-0.2/+8.7% \u2014 pulls 2025 CC down 1.77 TWh toward tolerance, 2023/24 stay in tol (no regression). oil 0.088/0.145/2.124 vs actual 0.39/0.31/0.91: recovers winter oil but OVERSHOOTS 2025 to +134% (the daily-AGT convexity, fitted not forecast-grade, builds too much oil at the 26 $/MMBtu winter spike). CT_PEAKER (-84%) and ST_GAS (-96%) unchanged \u2014 this lever does not touch the summer CT/ST wedge. Verdict: most effective single lever on the 2025 CC gap, but needs a damped basis convexity / oil-frac cap to stop the oil overshoot before it is a keeper. | CAMPD triangulation (completeness check on the +8.7% headline): on the same CEMS plant set, model/CAMPD CC = +16.6/+13.8/+19.0% (2023/24/25) and EIA-923/CAMPD = +17.9/+15.0/+9.6%. The 923-over-CAMPD premium is stable ~15-18% in 2023/24 but collapses to +9.6% in 2025 => EIA-923 CC_REGULAR 2025 is itself ~2.5 TWh UNDERCOUNTED (still filling in), not ground truth. Decompose the +8.7% (~4.6 TWh): ~2.5 TWh is 923 incompleteness, ~2 TWh is real over-dispatch (model +19% vs the ~15% CAMPD norm = the within-gas winter-oil/summer-CT-ST split). EIA-930 gas 60.1 ~= model 60.0 confirms the gas envelope is right. Real CC error ~+3-4%, not +8.7%; do not tune to the preliminary 923 bar.", "years": [2023, 2024, 2025], "iso": "NEISO", "file": "frontend/data/backcast/runs/2026-06-18-neiso-18-oil-agtdaily.js"}, {"id": "2026-06-18-neiso-19-ct-mustrun", "label": "neiso 19 ct mustrun", "date": "2026-06-18", "shorthand": "neiso-19-ct-mustrun", "definition": "neiso 19 (PROBE \u2014 rejected for the 2025 CC gap; informative on the CT wedge). Baseline (neiso 17) + --ct-mustrun-per-plant: forces each CT_PEAKER to its observed EIA-923 monthly net generation (the full reliability/reserve wedge, WEFOR/POF-exempt), vs baseline's sub-marginal --ct-deployment slice. CT_PEAKER TWh (model / EIA-923 %): 0.350 -15% / 0.356 -45% / 0.270 -46% (2023/24/25) vs baseline 0.084/0.052/0.079 (-80/-93/-84%) \u2014 recovers the wedge (2025 0.08->0.27; capped below 0.50 actual because the 2025 early-release 923 lists only 247 CT plants). Answers the candidate-B question: the reserve wedge (observed-energy floor) IS larger than the sub-marginal slice (cf. neiso 20 ct-deploy2x at 0.15 TWh). BUT CC_REGULAR barely moves: +8.7%->+8.4% in 2025 (-0.18 TWh, ~1:1 with the CT added) \u2014 the CT wedge is real but ~0.4 TWh, far too small to close the +4.6 TWh CC over-dispatch. ST_GAS (-95%) untouched (CT-only lever). 2023/24 CC stay in tol (-0.6/-0.7%). Verdict: correct physics, wrong magnitude for the headline gap; keep as the CT-class fix, not the CC fix.", "years": [2023, 2024, 2025], "iso": "NEISO", "file": "frontend/data/backcast/runs/2026-06-18-neiso-19-ct-mustrun.js"}, {"id": "2026-06-18-neiso-20-ct-deploy2x", "label": "neiso 20 ct deploy2x", "date": "2026-06-18", "shorthand": "neiso-20-ct-deploy2x", "definition": "neiso 20 (PROBE \u2014 rejected; negative control for the CT wedge). Baseline (neiso 17) + --ct-deployment-floor-frac 2.0: doubles the measured sub-marginal CT AS/RUC-deployment floor (0.08->0.15 TWh of forced energy). CT_PEAKER TWh (model / EIA-923 %): 0.113 -73% / 0.066 -90% / 0.096 -81% (2023/24/25) vs baseline 0.084/0.052/0.079 \u2014 barely moves (the sub-marginal slice is nearly exhausted at frac 1.0). CC_REGULAR unchanged at +8.7% in 2025 (-0.2/-0.3% in 2023/24, no regression, no improvement). Confirms the candidate-B contrast: the observed-energy reserve wedge (neiso 19 ct-mustrun, CT 0.27-0.36) is ~2-3x the sub-marginal deployment slice; scaling the slice is a dead end. Does nothing for the headline CC over-dispatch.", "years": [2023, 2024, 2025], "iso": "NEISO", "file": "frontend/data/backcast/runs/2026-06-18-neiso-20-ct-deploy2x.js"}, {"id": "2026-06-19-neiso-21-monthly-keeper", "label": "neiso 21 monthly keeper", "date": "2026-06-19", "shorthand": "neiso-21-monthly-keeper", "definition": "neiso 21 (KEEPER \u2014 measured monthly hub-basis overlay; no fitted daily-AGT curve). Base: --commitment --ct-deployment --hydro-backfill-year 2024 --hydro-eia930-monthly. CC_REGULAR (model / 923 %): 52.31 -0.1% / 56.48 -0.2% / 57.75 +8.7% (2023/24/25); 2023/24 in tolerance. RE-ANCHORED SCORING \u2014 the 2025 +8.7% is NOT a 4.6 TWh model error: (1) the gas envelope is correct \u2014 model gas 60.14 ~= EIA-930 60.09 (+0.1%), net_gen 107.28 ~= 107.15; (2) CAMPD/CEMS triangulation on the common CC plant set gives model/CAMPD = +16.7/+13.8/+19.0% (2023/24/25) and EIA-923/CAMPD = +17.9/+14.9/+10.4%. The 923/CAMPD ratio holds a stable ~+15-18% in 2023/24 but COLLAPSES to +10.4% in 2025 => the preliminary EIA-923 CC_2025 is ~2.2 TWh undercounted (still filling in), not ground truth. Decompose the +8.7% (~4.6 TWh over 923): ~2.2 TWh is 923 incompleteness, ~2 TWh is a small within-gas over-dispatch (model +19% vs its ~+15% CAMPD norm). Real CC error ~+3-4%, NOT +8.7%; the residual %-gap is benchmark incompleteness, not model error \u2014 do not tune CC down to the 53.1 preliminary-923 bar. The fitted --gas-hub-basis-daily daily-AGT overlay was REJECTED this session: its convexity is fitted to the backcast and tuning it to hit EIA-930 oil is curve-fitting a magic number, so the keeper stays on the measured monthly overlay.", "years": [2023, 2024, 2025], "iso": "NEISO", "file": "frontend/data/backcast/runs/2026-06-19-neiso-21-monthly-keeper.js"}, {"id": "2026-06-19-neiso-22-ccsteam-keeper", "label": "neiso 22 ccsteam keeper", "date": "2026-06-19", "shorthand": "neiso-22-ccsteam-keeper", "definition": "neiso 22 (KEEPER \u2014 supersedes neiso 21). Re-ran the monthly-keeper config (--commitment --ct-deployment --hydro-backfill-year 2024 --hydro-eia930-monthly) to integrate the combined-cycle steam-turbine unit-outage derate (eia_*_cc capacity coupling in campd-unit-outages-NEISO.csv; derivation-script level, NO magic numbers \u2014 the fitted daily-AGT convexity stays rejected), and fixed a poisoned gas-basis cell. VERDICT: NEISO is backcast-calibrated. CC_REGULAR 52.30/56.51/57.76 reproduces the keeper (52.31/56.48/57.75) within +/-0.03 TWh; gas within ~1% of EIA-930 all years (54.76/58.87/60.11 vs 55.47/59.64/60.09); LW hub $35.08/$40.52/$71.20 vs actual DA $36.82/$41.47/$67.86 (-4.7/-2.3/+4.9%); the 2025 monthly DA shape tracks actual within a few $/MWh every month. The CC-steam derate is a NEAR-NO-OP for NEISO \u2014 controlled A/B (only the outage CSV swapped) moves 2025 CC_REGULAR -0.02 TWh and LW price +$0.9; the fleet has the headroom to absorb it (adopt for cross-ISO consistency). SEPARATELY FIXED (commit aa62655): the 15:46 fetch-eia-gas-prices refresh (postdates neiso 21) wrote a +$13.46/MMBtu Aug-2025 AGT basis from the EIA MA citygate proxy \u2014 a winter-level summer-month LDC citygate average that drove modeled Aug-2025 LMP to $167 vs the actual $45.6 DA; replaced with the Jul/Sep interpolation (+0.04). Before a forecast run: the neighbor-convexity priced-import node is REQUIRED (the seam is a fixed measured schedule today), plus the derived daily-AGT winter-oil convexity when upload U4 lands (oil 0.00/0.00/0.06 vs EIA-930 0.32/0.37/1.24, LMP-neutral). Full diagnosis: results/calibration/DIAGNOSIS-neiso-ccsteam-2026-06-19.md; forecast-prep prompts: docs/multi-iso/neiso-forecast-prep-prompts.md. SYSTEM VOLUME ERROR FIX (render_calibration_html, incomplete-vintage benchmark repair): the 2025 fossil benchmark was raw preliminary EIA-923, under-counting CC by ~4 TWh (CC bench 53.12 vs model 57.76, which matches complete EIA-930 within 1%), inflating the 2025 system volume error to +7.25%. The benchmark now scales any fossil fuel whose grid 923 total is <0.97x the complete EIA-930 grid series up to that EIA-930 total (split/shape preserved); 2025 sys vol err +7.25% -> ~0%, complete vintages (2023 1.02x / 2024 1.02x) untouched. CEMS audit confirmed CEMS under-reads CC every year (44-49 vs 923's 52-57) so it is a shape source, not a level authority; the model is correct.", "years": [2023, 2024, 2025], "iso": "NEISO", "file": "frontend/data/backcast/runs/2026-06-19-neiso-22-ccsteam-keeper.js"}, {"id": "2026-06-19-pjm-33-miso-reanchor", "label": "pjm 33 miso reanchor", "date": "2026-06-19", "shorthand": "pjm-33-miso-reanchor", "definition": "Forecast-grade reference-price interchange seam (pjm_32 lineage) with the dominant MISO seam now anchored entirely to MISO's OWN measured Indiana-Hub RT LMP (fetched from docs.misoenergy.org), replacing estimates (claude.md #12): marginal heat rate 14.2->12.9 (14.2 used the IMM ~$36 all-footprint average; the border Indiana Hub measures $31.8/$30.8/$42.85 = LMP/HH 12.5/14.1/12.2, mean 12.9 -> 14.2 over-priced the border by +13%/+17% in 2023/2025) and convexity 1.63->1.60 (self-derived, R2 0.24 -- confirms the borrow was sound, so convexity was NOT the over-export driver; the level was). derive_neighbor_convexity --check now guards both. RESULT vs pjm_32: net export corrects toward measured every year -- 2024 +34%->+1.8% (33.3 vs 32.7 TWh, near-perfect), 2025 +112%->+30% (23.4 vs 18.0), 2023 +56%->+32% (52.7 vs 40.0); in-tol fails 7->5; 2024 now fully passes (coal-tot +1.0%, gas +4.8%). HONEST TRADE-OFF: with interchange correctly sized the LMP under-run is no longer masked by over-export -- 2025 LMP -13.7% (was pjm_32 -10.5%, pjm_28 -16.8%), 2024 -6.4%, 2023 +2.1% -- revealing the residual under-run is PJM's OWN price-formation gap (scarcity/congestion/reserve adders the energy-only LP omits), NOT interchange. Residual coal-over in 2023/2025 (+7%) is the forecast-native single MISO HR (12.9) slightly over-pricing those years (their measured ratios 12.5/12.2 < 12.9); a per-year HR would close it but isn't forecastable. Most structurally faithful PJM run to date (every seam parameter measured from the neighbor's own data, nothing tuned to PJM flow, rule #11); pjm_28 remains the lowest-fail FITTED reference.", "years": [2023, 2024, 2025], "iso": "PJM", "file": "frontend/data/backcast/runs/2026-06-19-pjm-33-miso-reanchor.js"}, {"id": "2026-06-19-pjm-34-coal-rank", "label": "pjm 34 coal rank", "date": "2026-06-19", "shorthand": "pjm-34-coal-rank", "definition": "pjm_33 lineage (forecast-grade reference-price interchange seam, MISO reanchor) + a CORRECTNESS fix to coal-rank labeling: three retiring PJM coal plants \u2014 W H Sammis (OH), Homer City (PA), AES Warrior Run (MD), all bituminous \u2014 were stuck in the model's generic unranked COAL bucket because coal_supply_class consulted only the curated + EIA-923 fuel-receipt maps, and a mid-backcast retiree has no recent burned-fuel receipts to derive a rank from. The EIA-923 benchmark already resolves them to COAL_BIT via fuel code, so the model showed a spurious generic 'Coal' row the actual never has AND priced them at generic full cost instead of PJM's bituminous passthrough. FIX (data.fleet.coal_supply_class): a tertiary EIA-860 energy_source fallback scoped to the retired-within-window vintage (the exact structural gap; operable coal untouched), mirroring the benchmark's fuel-code fallback. PJM coal now fully resolves (32 bituminous, 0 unranked); 212 fleet/coal tests pass. KEY FINDING \u2014 the dashboard's '+7%' 2023 coal-over was a LABELING ARTIFACT: the coal-tot gate sums only BIT+PRB+WC, so it compared model-coal-MINUS-the-3-retirees (~13 TWh hidden in the excluded generic bucket) against actual-coal-that-INCLUDES-them. Apples-to-apples the 2023 coal-over is +18.7% (+21 TWh), not +7%; total model coal barely moved (136.7->134.8 TWh, repricing ~dispatch-neutral) \u2014 only the attribution became honest. SCORECARD vs actual (coal-tot %; LMP %): 2023 coal-tot +18.7% (was +6.9%), COAL_BIT +20.0%, gas +2.2%, LMP +2.4%, net-export +29.6% | 2024 coal-tot +3.9% (was +1.0%, still PASS, 0 fails), LMP -6.3% | 2025 coal-tot +7.5% (UNCHANGED from pjm_33 \u2014 no retirees operating, so this is the GENUINE coal-over, not labeling), LMP -13.7%. in-tol fails 5 (same count as pjm_33; 2023 COAL_BIT/coal-tot, 2025 COAL_BIT/COAL_PRB/coal-tot). ROOT CAUSE now visible: ~half the 2023 coal-over is the 3 retirees over-dispatching (Homer City model 9.1 vs 1.0 TWh actual) \u2014 part a COD-ramp partial-retirement bug (load_cod_map collapses heterogeneous unit-retirement dates to the latest, so Homer City runs 2 units that retired Jul/Aug through year-end; small-scope 4-plant cross-ISO fix deferred), part the dominant economic over-dispatch of cheap uneconomic retirees the energy-only LP runs as baseload (needs CAMPD unit-level availability, not a fit). LMP/interchange unchanged vs pjm_33; this run makes the coal scorecard HONEST (faithfulness over MAE) and supersedes pjm_33's misleading coal-over.", "years": [2023, 2024, 2025], "iso": "PJM", "file": "frontend/data/backcast/runs/2026-06-19-pjm-34-coal-rank.js"}, {"id": "2026-06-19-pjm-35-cc-steam", "label": "pjm 35 cc-steam rebaseline", "date": "2026-06-19", "shorthand": "pjm-35-cc-steam", "definition": "KEEPER. Re-baseline of the pjm_34 recipe (pjm_28 config + forecast-grade reference-price interchange seam + neighbor price-vs-load convexity) on the CC steam-turbine outage coupling now in main: a CC's CT outage derates its full block (CT + the steam it fed) instead of the CT alone, so the steam is no longer phantom-available during CT outages. Nothing tuned to PJM's net-MWh/price residual. Coal-tot over: 2023 +15.7% (was pjm_34 +18.7%), 2024 +5.0% (+3.9%), 2025 +8.7% (+7.5%); gas in tolerance all years (+1.4/+3.6/+3.0%). FINDING: the bituminous 0.76 passthrough floor is NOT the coal-over lever \u2014 2025 has zero retirees yet COAL_BIT overs +7.8% at a ~1.08 passthrough (near full fuel cost, $3.52 gas ~ gas_mid 3.40), and the over runs INVERSE to the cheap-gas discount (2024 deepest discount 0.79 -> smallest over). Residual coal-over is structural (operable-coal baseload + 2023/24 retiree over-dispatch: Homer City/Sammis/Warrior Run 6.25 TWh in 2023, 3.2 in 2024, 0 in 2025), addressable only by measured COD fractional-retirement + CAMPD unit availability, not by tuning the passthrough.", "years": [2023, 2024, 2025], "iso": "PJM", "file": "frontend/data/backcast/runs/2026-06-19-pjm-35-cc-steam.js"}, {"id": "2026-06-20-pjm-36-retiree-cems", "label": "pjm 36 retiree cems", "date": "2026-06-20", "shorthand": "pjm-36-retiree-cems", "definition": "NEW KEEPER (supersedes pjm 35 cc-steam). pjm_35 config + within-window retiree CEMS measured-availability cap (retiree_cems_cap=True): each within-window retiree plant is limited to its measured monthly CAMPD CEMS envelope (zero in months it did not run), honestly reflecting the out-of-market retirement economics a cost-based LP cannot see \u2014 nothing tuned to the coal/net-MWh target. Closes the Homer City (3122) phantom-baseload over: model 4.40/2.79/0.00 \u2192 1.48/0.00/0.00 TWh vs CEMS 1.20/0.00/0.00. Two compounding fixes: (a) per-unit COD retirement in cod_ramp (effective_cod no longer collapses heterogeneous unit retirements to the latest date) \u2014 MAE-neutral alone, the per-plant binning merges units before the ramp; (b) the CEMS cap, which moves the aggregate. Coal-tot: 2023 +15.7%\u2192+13.8%, 2024 +5.0%\u2192+3.1% (now PASS), 2025 +8.7% unchanged (no running retirees \u2014 clean blast radius). In-tolerance fails 7\u21925; freed retiree energy split between gas (stays PASS) and reduced 2023 over-export (interchg +15.0%\u2192+11.6%). Finding: the residual operable-coal over (2025 +7.8% BIT, confound-free) is system merit-order, NOT a retiree-capacity issue.", "years": [2023, 2024, 2025], "iso": "PJM", "file": "frontend/data/backcast/runs/2026-06-20-pjm-36-retiree-cems.js"}, {"id": "2026-06-21-neiso-23-outage-btm", "label": "neiso 23 outage-btm-basis", "date": "2026-06-21", "shorthand": "neiso-23-outage-btm", "definition": "neiso 23 (KEEPER \u2014 supersedes neiso 22). Two folded, independently-attributable changes re-solved in one byte-faithful pass off the neiso-22 run_config (scripts/run_calibration_full.py --iso NEISO --year 2023 2024 2025 --commitment --ct-deployment --hydro-backfill-year 2024 --hydro-eia930-monthly; gas-hub-basis monthly overlay on by default). TASK A \u2014 OUTAGE RE-GATE (model-side): swapped in the net-load-filtered (revealed-availability) data/raw/campd-unit-outages-NEISO.csv (branch claude/ercot-scarcity-tuning-handoff-nl1y3m @ b0c41cb), capacity-weighted outage GW-days 6150->4049 (-34%; summer binding preserved, shoulder/winter economic-idle mass cut). Everything else identical -> the dispatch/system/storage parquets are the pure outage delta. Near-no-op on dispatch, as expected from the keeper's headroom: CC_REGULAR 52.34/56.54/57.89 TWh (keeper 52.31/56.48/57.75; +0.03/+0.06/+0.14). Cooler shoulder/winter LMP, the expected revealed-availability direction: load-wtd hub $34.06/$39.00/$69.60 (keeper $35.08/$40.52/$71.20; vs actual DA $36.82/$41.47/$67.86 -> -7.5%/-6.0%/+2.6%, was -4.7/-2.3/+4.9%). FLAG: 2023/24 now run ~6-7.5% below actual DA (a ~$1-1.5 cooling) \u2014 modest, not an under-fire; summer/tail preserved (zone-avg hrs>$200: 0/0/13). TASK B \u2014 CHP BTM BASIS FIX (benchmark-side; solve-invariant): the grid LP holds out behind-the-meter CHP host self-supply for ALL ISOs, so gmModel is grid-delivered only, but btm.parquet was written ERCOT-only (run_calibration_full.py gated btm_frames.append on is_ercot). NEISO render fell back to FULL EIA-923 (BTM included) vs a grid-only model -> a false ~1.3 TWh/yr CHP shortfall (~60% of the prior -3.8/-4.1% 2023/24 system volume error). FIX: removed the is_ercot gate so _btm_frame runs for every ISO, building the per-plant CHP bin frame from the year's EIA-860 fleet group map (the non-ERCOT analogue of the curated CAMPD bin sheet) instead of the ERCOT-only sheet; plant codes parsed numeric-head like the dispatch frame. btm.parquet CHP btm_twh now present: CC_CHP 0.58/0.66/0.52, CT_CHP 0.56/0.53/0.13, ST_CHP ~0 (model slightly over-produces ST_CHP, so 923-grid clips to 0 \u2014 within abs band, not chased). classFull = EIA-923 - per-class BTM now lands on gmModel: CC_CHP 1.35/1.36/1.48 vs model 1.36/1.35/1.44 (|d|<=0.04, in tolerance all 3 yrs); CT_CHP (gate-excluded) 1.04/1.03/0.33, within +/-1 TWh abs. SYSTEM GAS VOLUME ERROR 2023 -1.3% / 2024 -1.6% / 2025 +0.4% (down from -3.8/-4.1% on the false full-923 basis; CC_REGULAR -0.04%/-0.13%/+0.75% vs classFull). 2025 stays ~0% anchored by the EIA-930 incomplete-vintage reconcile (render _VINTAGE_RECONCILE_FRAC=0.97; gas scaled x1.082, complete 2023/24 untouched at 1.001/1.005); the uniform reconcile re-inflates 2025 CC_CHP classFull 1.36->1.48 but model 1.44 still sits inside tolerance, so no CC_REGULAR-concentration override was needed. Fixing at the source (btm.parquet) keeps render, session_score, compare_runs_classes and the offer-curve Jacobian on the same grid-delivered basis. The remaining ~0.8 TWh of the 2023 system gap is small peaker/steam classes the model zeroes (CT_PEAKER, ST_GAS, COAL_BIT) \u2014 real tiny dispatch differences within +/-1 TWh abs, NOT a reporting artifact; not conflated with the BTM basis. FOLLOW-UP (out of scope here): the same BTM gate fix will correctly affect the PJM/CAISO/NYISO keepers once their bundles regenerate btm.parquet \u2014 re-register those later. Carries forward all neiso-22 forecast-prep caveats (priced-import seam node REQUIRED before a forecast run; daily-AGT winter-oil convexity stays rejected as curve-fitting). Full neiso-22 diagnosis: results/calibration/DIAGNOSIS-neiso-ccsteam-2026-06-19.md.", "years": [2023, 2024, 2025], "iso": "NEISO", "file": "frontend/data/backcast/runs/2026-06-21-neiso-23-outage-btm.js"}, {"id": "2026-06-21-nyiso-14-som-anchored", "label": "nyiso 14 som-anchored-gas", "date": "2026-06-21", "shorthand": "nyiso-14-som-anchored", "definition": "(PROBE \u2014 confirms the mechanism-D diagnosis but not a clean fix.) Third gas-series test, built from ONLY sourced data after the 'isn't the monthly citygate already in the repo?' question: gas level = Henry Hub MONTHLY shape (EIA RNGWHHDm) re-levelled to the NYISO State-of-the-Market MARGINAL-hub ANNUAL value (nyiso_zonal_gas_hub.csv, Iroquois Z2 at the Capital reference), zonal basis spreading the rest; replaces both the winter-high EIA-923 receipts and the summer-high EIA citygate. RESULT: Jan-2023 residual collapses +44 -> +4 (gas vs EIA-923 -0.5%->-2.8%, in band) -- PROVING the 2023 winter over-price is the gas series, not scarcity. BUT the SOM anchor is ANNUAL-only: a flat annual level x Henry Hub's near-flat monthly shape cannot reproduce a winter-weighted hub, so non-winter months over-level (+~10/mo) and 2025 -- whose SOM annual $6.02 is dominated by the Jan cold-snap blowout -- smears across summer and explodes. Monthly LMP MAE 8.0/4.3/6.3 -> 9.3/9.0/18.7 (net worse); rejected. Decisive finding: the repo's receipts (winter-high), EIA citygate (summer-high, an LDC $/Mcf series that PEAKS in summer), and annual SOM hub BRACKET the truth but none is it; the clean fix needs the MONTHLY (or daily) Transco-Z6 NY / Iroquois-Z2 trading-hub SPOT (NGI/ICE/Platts or NYISO reference-level), which EIA does not publish free. See docs/nyiso-backcast-residual-attribution-2026-06.md.", "years": [2023, 2024, 2025], "iso": "NYISO", "file": "frontend/data/backcast/runs/2026-06-21-nyiso-14-som-anchored.js"}, {"id": "2026-06-21-nyiso-15-transco-z6", "label": "nyiso 15 transco z6", "date": "2026-06-21", "shorthand": "nyiso-15-transco-z6", "definition": "Mechanism-D gas fix: keeper + --gas-hub-basis-overlay with the NYISO basis rebuilt from the REAL monthly EIA NG Weekly Transco Z6 NY spot ('New York'), lifted to the Iroquois Z2 reference level by the SOM annual inter-hub spread; zonal basis spreads NYC back to Transco. Fixes the dominant Jan-2023 winter artifact (resid +44 -> +7.4; 2023 monthly-LMP MAE 8.0 -> 5.6); 2024/25 MAE 5.9/7.5 and 2025 net-interchange 117.5%. Monthly mean still smears extreme-cold months (Jan-2025 +39) -> next is DAILY Transco resolution + a real monthly Iroquois. | BTM RE-SCORE (2026-06-22): byte-faithful re-solve (gmModel reproduces the keeper to <0.1%) + btm.parquet (CC_CHP 3.3-4.8/CT_CHP/ST_CHP TWh) -> CHP scored grid-delivered; 2024 CC_CHP clears (was -2.93). C6 governance PASS (attestation). DETERMINATION: NOT-YET. Deciding fails are MODEL MISSes (not ledgerable): CC_REGULAR -7.1/-13.3/-7.9% under-dispatch (no BTM; gas-basis/interchange merit), gas family +5.4/-10.6/-7.3%, ST_GAS +-2-4 TWh; 2023/25 CC_CHP +2.3/+2.9 over their measured 923 grid output.", "years": [2023, 2024, 2025], "iso": "NYISO", "file": "frontend/data/backcast/runs/2026-06-21-nyiso-15-transco-z6.js"}, {"id": "2026-06-21-pjm-38-outage-regate", "label": "pjm 38 outage regate", "date": "2026-06-21", "shorthand": "pjm-38-outage-regate", "definition": "NEW KEEPER (supersedes pjm 36 retiree-cems). The pjm 36 keeper config (retiree_cems_cap=True) re-solved byte-faithfully on the net-load-filtered outages (commit b0c41cb), changing ONLY the outage input \u2014 the cross-ISO revealed-availability filter that cut PJM capacity-weighted outage GW-days ~46% (concentrated Apr/Oct, summer preserved). Promoted under right-structure-first: the net-load filter is the forecast-defensible exogenous outage input (keys on net load, not price). Honest gate result (NOT clean \u2014 accepted as forecast-native, see docs/multi-iso/pjm-outage-regate-2026-06.md): the cooler shoulder/winter availability lets the cost-based LP run the freed cheap take-or-pay coal/CC, amplifying PJM's documented forecast-native coal over-run + over-export. Coal-tot resid 2023 +6.8->+17.3%, 2024 -2.2->+13.9%, 2025 +2.4->+22.8%; net-export +11.6->+69% / -11.8->+65% / +28->+204%; in-tolerance fails 3->11. LMP cools further below actual (load-wtd mean 30.09->28.12 / 28.06->26.17 / 37.81->34.63; lwt-MAE 8.30->8.12 / 10.46->10.49 / 15.06->15.82; hrs>$200 0/0/0 unchanged). The coal-over/export is the next frontier (offer-curve / coal-cost retune), not chased here. | BTM RE-SCORE / FIRST REGISTRATION (2026-06-22): pjm_38 was a stub (no payload); re-solved its committed keeper config from meta.json, writing btm.parquet + full payload + bench. C6 governance PASS (attestation). DETERMINATION: NOT-YET. Deciding fails are MODEL MISSes (not ledgerable): C2 coal +17.3/+13.9/+22.8% (the documented PJM structural coal over-run, a SEPARATE issue amplified by the net-load re-gate, not folded in here), CT_PEAKER -18/-33% under, CC_CHP +1-2 over measured 923 grid, C3a LMP -11.4/-19.3% (2024/25). C4 PASS.", "years": [2023, 2024, 2025], "iso": "PJM", "file": "frontend/data/backcast/runs/2026-06-21-pjm-38-outage-regate.js"}, {"id": "2026-06-22-caiso-19-outage-regate", "label": "caiso 19 outage regate", "date": "2026-06-22", "shorthand": "caiso-19-outage-regate", "definition": "3-YEAR re-gate of the caiso-15 all-flags keeper (commitment, priced-interchange, 2024 hydro repin + EIA-930 monthly, gas-hub-basis overlay, import gas-coupling + solar-shape) on the net-load-filtered CAMPD unit-outages (commit b0c41cb). Byte-faithful; only the outage input changed. 2024 reproduces caiso-18 (the 2024-only re-gate) EXACTLY (mean 41.17, neg 408 @ 91.9% precision), confirming 3-yr consistency. LMP gating (vs actual DA; 2023 has no actual LMP yet -> fuel-mix-gated only): 2024 mean 41.17 vs actual 35.85 (resid +5.32), neg 408 @ 91.9%/recall 49.7%; 2025 mean 49.31 vs actual 34.62 (resid +14.69), p95 79.81 vs 58.87 (+20.94), neg 16 vs 561 (prec 37.5%, recall 1.1%) -- 2025 runs structurally HOT and misses the negative tail (a known open issue, not introduced here). Model system price avg: 2023 62.17, 2024 41.17, 2025 49.31. Gas TWh vs EIA-923: 2023 66.15/76.04 (-13%), 2024 71.85/67.68 (+6%), 2025 71.32/55.18 (+29%). The CC-over/peaker-under mix defect (TASK-2, a commitment/merit-order property) persists across all 3 years. Companion to the 2024-only caiso-18; see DIAGNOSIS-caiso-fleet-mix-outage-2026-06-21.", "years": [2023, 2024, 2025], "iso": "CAISO", "file": "frontend/data/backcast/runs/2026-06-22-caiso-19-outage-regate.js"}, {"id": "2026-06-22-miso1-baseline", "label": "miso1 baseline", "date": "2026-06-22", "shorthand": "miso1-baseline", "definition": "Calibration run from bundle miso1_baseline.", "years": [2023, 2024, 2025], "iso": "MISO", "file": "frontend/data/backcast/runs/2026-06-22-miso1-baseline.js"}, {"id": "2026-06-22-neiso-24-local-band", "label": "neiso 24 local band", "date": "2026-06-22", "shorthand": "neiso-24-local-band", "definition": "neiso 24 local-band outage regate (NEW KEEPER, supersedes neiso 23). The neiso-23 keeper config (scripts/run_calibration_full.py --iso NEISO --year 2023 2024 2025 --commitment --ct-deployment --hydro-backfill-year 2024 --hydro-eia930-monthly; gas-hub-basis monthly overlay on by default; CHP BTM basis fix in code) re-solved BYTE-FAITHFULLY on the LOCAL (seasonal) net-load outage band \u2014 high_load_mask now uses a centered rolling +/-30d window (commit 152bb99) instead of a single annual percentile, recovering genuine multi-week shoulder maintenance outages. ONLY the outage input changed vs neiso 23 (regenerated data/raw/campd-unit-outages-NEISO.csv, auto picked up). NEAR-NO-OP as predicted by the keeper's dispatch headroom (neiso-23 noted the same for the annual-band re-gate): CC_REGULAR 52.32/56.48/57.75 TWh (neiso-23 52.34/56.54/57.89; |d|<=0.14); system gas volume error -1.5%/-1.4%/+0.2% (neiso-23 -1.3/-1.6/+0.4). LMP demand-wtd model mean 33.93/39.23/68.33 (neiso-23 34.06/39.00/69.60; vs actual DA 36.82/41.47/67.86 -> -7.8%/-5.4%/+0.7%, marginally closer to actual on 2024/2025, ~flat 2023). Hourly hub MAE 15.23/14.11/21.60. TAIL PRESERVED: model hrs>$200 0/0/13 (IDENTICAL to neiso-23; actual 72/43/290) \u2014 summer/winter scarcity neither collapsed nor re-inflated (2025 model max $258.98). The local band is the forecast-defensible exogenous outage input (keys on net load, not price) and produces an equivalent-or-marginally-better calibration; adopted as the keeper-of-record on the correct input. Carries forward all neiso-23/neiso-22 caveats (priced-import seam node required before a forecast run; daily-AGT winter-oil convexity stays rejected).", "years": [2023, 2024, 2025], "iso": "NEISO", "file": "frontend/data/backcast/runs/2026-06-22-neiso-24-local-band.js"}, {"id": "2026-06-22-neiso-25-fullstop-override", "label": "neiso 25 fullstop override", "date": "2026-06-22", "shorthand": "neiso-25-fullstop-override", "definition": "neiso 25 fullstop-override outage re-gate (NEW KEEPER, supersedes neiso 24). The neiso-24 keeper config (run_calibration_full.py --iso NEISO --year 2023 2024 2025 --commitment --ct-deployment --hydro-backfill-year 2024 --hydro-eia930-monthly; monthly gas-hub-basis overlay on by default; CHP BTM basis fix in code) re-solved on the SHARED FULL-STOP DURATION OVERRIDE outage input (commits 56ca468/debad10): filter_revealed_outages now keeps a detected down-span if it overlaps >=24 high-net-load hours OR is a sustained full stop (span mean-CF<0.02) for >=14 continuous days, recovering the thin layer of genuinely-mechanical 14-20d weeks-long dead stops the local band still dropped at the 24h overlap margin. Measured-only (CAMPD CF + EIA-930 net load), one shared N=14/depth across all ISOs, no per-ISO constant, no price/MWh-residual (claude.md #11/#12: keep real measured outages). NEISO recovered +39 windows / 15 spans (Merrimack coal, Granite Ridge/Newington/Westbrook/Bellingham CC, Stony Brook, Pittsfield), 0.6% of detected GW-days, all small units; the STEP-1 audit (docs/multi-iso/outage-gate-fullstop-override-2026-06.md) predicted a near-no-op for NEISO and it is. ONLY the outage CSV changed vs neiso 24 (auto picked up). RESULT vs neiso 24: gas tot 54.82/58.92/60.32 TWh vs EIA-930 55.47/59.64/60.09 -> -1.2%/-1.2%/+0.4% (neiso-24 -1.5/-1.4/+0.2, marginally CLOSER to EIA-930 on 2023/24); CC_REGULAR 52.35/56.50/57.88 (neiso-24 52.32/56.48/57.75; |d|<=0.13). LMP model mean 33.96/39.24/68.74 (neiso-24 33.93/39.23/68.33) vs actual DA 36.82/41.51/67.86 -> -7.8%/-5.5%/+1.3%. Hourly hub MAE vs actual RT 15.24/14.10/21.64 (IDENTICAL to neiso-24 15.23/14.11/21.60). TAIL PRESERVED: model hrs>$200 0/0/14 (neiso-24 0/0/13; actual RT 72/43/290), 2025 model max $258.98 unchanged -- the recovered winter full-stops (Granite Ridge/Merrimack Feb 2025) add exactly one marginal 2025 scarcity hour, neither collapsing nor re-inflating the tail. The full-stop override is the structurally-correct forecast-defensible exogenous outage input (keys on net load + measured CF, regenerates forward) and produces an equivalent-or-marginally-better calibration; adopted as keeper-of-record on the correct input. Carries forward all neiso-24/23/22 caveats: priced-import seam node REQUIRED before a forecast run (imports on a fixed EIA-930 schedule); winter oil under-generation (model 0.00/0.00/0.06 vs EIA-930 0.32/0.37/1.24 TWh) is the monthly-AGT-granularity limit and the dominant remaining residual -- the >$200 winter tail (0/0/14 vs 72/43/290) is downstream of it; daily-AGT winter-oil convexity stays REJECTED as a fitted constant (derive from measured daily AGT spot, upload U4).", "years": [2023, 2024, 2025], "iso": "NEISO", "file": "frontend/data/backcast/runs/2026-06-22-neiso-25-fullstop-override.js"}, {"id": "2026-06-22-nyiso-16-transco-daily", "label": "nyiso 16 transco-daily-gas", "date": "2026-06-22", "shorthand": "nyiso-16-transco-daily", "definition": "Mechanism-D fix #1(a): DAILY Transco Z6 NY gas overlay. Keeper config + --gas-hub-basis-overlay --gas-hub-basis-daily, where the overlay's within-month shape is the REAL measured EIA NG Weekly Transco Z6 NY daily spot (scripts/fetch_transco_daily_spot.py -> transco_z6_ny_daily.csv, 674 trading days; daily monthly means reproduce the nyiso-15 monthly file to <$0.06, captured Henry Hub matches EIA RNGWHHD to $0.02). _nyiso_hub_daily_gas_prices scales that shape onto the monthly Iroquois-Z2 level, EXACTLY mean-preserving (annual gas burn/mix unchanged). VALIDATED positive (not a probe): does what the nyiso-15 monthly overlay could not -- Jan-2025 within-month smear fixed (+39.3 -> -1.97), 2025 summer under-price lifted (Jul -10 -> -1.1); monthly-LMP MAE 5.1/5.7/5.1 (keeper 8.0/4.3/6.3, monthly-15 5.6/5.9/7.5) -- best NYISO MAE on 2023 and 2025 and best average; and it RESTORES the 2025 net-interchange band the monthly overlay broke (117.5% OUT -> 109.8% IN, mean-preserving daily shape no longer pushes the annual import level out). Breaks NO volume band the keeper holds: every band where the keeper is in, daily is in (2025 interchange improved); every band where daily is out (2024/25 gas -9.8%/-6.2% vs EIA-930, 2023 interchange 74.2%) the keeper sits on the same EIA-930/923 basis floor by the same margin (keeper 2024 gas re-measured -8.8%). Keeper nyiso 11 STILL STANDS, gated on two non-daily-lever items: (1) the flat-annual Iroquois-Transco spread over-levels summer (Jul/Aug +10) -- fix #1(b), a real monthly Iroquois Z2 (EIA free has none), still data-blocked; (2) Dec-2024 -27.5 is the now-unmasked mechanism-B RCPF scarcity tail (actual RT $67.8), not mechanism D. Supersedes the keeper once #1(b) lands and B fills the winter tail. Zero tuning; every input sourced. See docs/nyiso-backcast-residual-attribution-2026-06.md section 4e.", "years": [2023, 2024, 2025], "iso": "NYISO", "file": "frontend/data/backcast/runs/2026-06-22-nyiso-16-transco-daily.js"}, {"id": "2026-06-22-nyiso-17-local-band", "label": "nyiso 17 local band", "date": "2026-06-22", "shorthand": "nyiso-17-local-band", "definition": "nyiso 17 local-band outage regate (local-band re-solve of the nyiso-16 daily-Transco lineage). The nyiso-16 config (nyiso-11 keeper + --gas-hub-basis-overlay --gas-hub-basis-daily: measured EIA Transco Z6 NY daily spot within-month shape, mean-preserving on the monthly Iroquois-Z2 level; commitment + priced interchange + NYISO harness defaults) re-solved BYTE-FAITHFULLY on the LOCAL (seasonal) net-load outage band \u2014 high_load_mask centered rolling +/-30d window (commit 152bb99) instead of the single annual percentile. ONLY the outage input changed (regenerated data/raw/campd-unit-outages-NYISO.csv, auto picked up); the committed CSV is now the forward-correct NYISO outage input. Daily Transco overlay confirmed firing (658 gas gens repriced 12/12 months, winter max $30.19/MMBtu). Canonical gate (model vs actual RT): 2023 annual mean $36.44 vs $30.29 (+6.16; over-prices winter/shoulder \u2014 the documented flat-annual Iroquois-Transco summer over-level / fix #1(b), data-blocked), 2024 $37.57 vs $35.98 (+1.60; Dec -27.18 is the unmasked mechanism-B RCPF winter scarcity tail, not mechanism D), 2025 $61.19 vs $60.73 (+0.46; Jan -3.0, Jul -4.6). Model hrs>$200 1/0/57 (actual 31/27/119) \u2014 summer/winter tail present, not collapsed. NYISO has keeper dispatch headroom (imports/hydro/nuclear), so the outage re-gate is near-equivalent to nyiso-16. NOTE: a byte-clean A/B vs nyiso-16 is basis-limited \u2014 its bundle parquets are gitignored \u2014 so this is reported on absolute gate, not delta. Keeper-of-record nyiso 11 STILL STANDS (the daily-Transco overlay supersedes only once fix #1(b) lands and mechanism-B fills the winter tail, per nyiso-16); this run carries the forward-correct local-band outage input into that lineage.", "years": [2023, 2024, 2025], "iso": "NYISO", "file": "frontend/data/backcast/runs/2026-06-22-nyiso-17-local-band.js"}, {"id": "2026-06-22-nyiso-18-local-floors", "label": "nyiso 18 local floors", "date": "2026-06-22", "shorthand": "nyiso-18-local-floors", "definition": "(PROBE) Long Island local self-supply floor (NYISO LMIC, frac 0.45) + HQ/Ontario firm-import baseload. STRUCTURAL fix: LI in-zone generation 3.7->9.3 TWh (real 8.5) \u2014 the -4.8 TWh dispatch error is fixed and the LI dual-fuel units fire. Price MAE 8.2/4.0/10.9 (keeper ~8.0/4.3/6.0): 2024 better, but the floor adds cheap forced supply on top of the already-missing scarcity tail and worsens 2025 (Jun/Jul -22..-31). Per rule #1 the structurally-correct floor stays in code (default OFF); it becomes a keeper once the scarcity tail (fix #3 / in-LP reserve co-optimization for NYC peakers) lands. See docs/nyiso-dispatch-validation-2026-06.md.", "years": [2023, 2024, 2025], "iso": "NYISO", "file": "frontend/data/backcast/runs/2026-06-22-nyiso-18-local-floors.js"}, {"id": "2026-06-22-nyiso-19-locational-reserve", "label": "nyiso 19 locational reserve", "date": "2026-06-22", "shorthand": "nyiso-19-locational-reserve", "definition": "(PROBE) Fix #3: in-LP LOCATIONAL reserve co-optimization for NYISO (NYCA-system plus nested East/SENY/NYC RCPF families, FERC ER21-502 / RS4 anchors), on top of the LI self-supply + firm-import floors (--energy-reserve-coopt --nyiso-local-selfsupply --nyiso-firm-imports). Holding the import-constrained downstate pocket to its locational reserve recovers the summer scarcity tail the NYCA-aggregate curve and the post-solve RCPF adder cannot dispatch: reserve fires only in genuine summer scarcity (Jul/Aug/Sep), 2025 summer under-bias eased (Jun -30.7->-14.6, Jul -22.1->-15.8 vs the LI-floor probe), 2025 price_shape now PASSES (NRMSE 0.16) and 2024 price fully PASSES, dispatch r 0.81-0.87 all years. NOT a keeper: the aggregate is gated by a PRE-EXISTING winter/January downstate over-pricing (2023 price_mean +13%, shape 0.402) that a BASE-vs-COOPT A/B proved is identical with the co-opt off (a gas/dual-fuel marginal-unit residual, the next root cause) -- so it does not beat keeper nyiso-11. Per rule #1 the mechanism stays (default OFF).", "years": [2023, 2024, 2025], "iso": "NYISO", "file": "frontend/data/backcast/runs/2026-06-22-nyiso-19-locational-reserve.js"}, {"id": "2026-06-22-pjm-39-local-band", "label": "pjm 39 local band", "date": "2026-06-22", "shorthand": "pjm-39-local-band", "definition": "pjm 39 local-band outage regate (NEW KEEPER, supersedes pjm 38). The pjm-38 keeper config (retiree_cems_cap=True) re-solved BYTE-FAITHFULLY on the LOCAL (seasonal) net-load outage band \u2014 scripts/derive_campd_outages.py high_load_mask now measures the high-load percentile over a centered rolling +/-30d window (commit 152bb99) instead of a single annual percentile, recovering genuine multi-week shoulder CCGT maintenance outages the annual band wrongly dropped while still dropping short economic-idle gaps. ONLY the outage input changed vs pjm 38 (both regenerated data/raw/campd-outages-PJM.csv facility + campd-unit-outages-PJM.csv unit, auto picked up); no offers/curves/flags retuned. Direction as predicted: recovering shoulder outages puts MORE coal/CC offline in shoulder months -> firmer prices and LESS of the annual-band coal over-run/over-export. STRICT IMPROVEMENT over pjm 38 on every axis. LMP demand-wtd mean (model vs actual RT) 28.29/26.12/35.01 (pjm38 28.12/26.17/34.63; actual 28.44/29.53/42.89); hourly hub MAE 7.94/9.75/13.37 (pjm38 8.12/10.49/15.82 \u2014 better all 3 yrs); coal-tot resid +11.4/+3.0/+11.1% (pjm38 +17.3/+13.9/+22.8); net-export resid +31/+17.5/+93% (pjm38 +69/+65/+204); in-tolerance fails 11->7. Model hrs>$200 0/0/0 unchanged (actual 6/18/59) \u2014 the model still does not fire PJM's scarcity tail, a documented SEPARATE issue, neither collapsed nor re-inflated here. Summer not under-fired (2023 Jul/Aug model 29.1 vs actual 31.8). Remaining coal over-run + over-export is PJM's documented forecast-native coal-cost/offer issue (docs/multi-iso/pjm-coal-mustrun-floor.md), made LESS visible than the annual band rather than newly introduced \u2014 the next frontier, not chased in the outage step. [merged 2023-25 from parallel per-year solves]", "years": [2023, 2024, 2025], "iso": "PJM", "file": "frontend/data/backcast/runs/2026-06-22-pjm-39-local-band.js"}, {"id": "2026-06-22-pjm-40-coal-fidelity", "label": "pjm 40 coal fidelity", "date": "2026-06-22", "shorthand": "pjm-40-coal-fidelity", "definition": "pjm_40_coalfidelity: pjm_39 local-band config (verbatim) + the heat-input->MWh proxy for grossLoad-blank coal + the coal-cogen CHP/BTM holdout (Eastman/St Nicholas/John B Rich/...). Measured-anchored, no new flags; 2023 only [merged 2023-25 from parallel per-year solves]", "years": [2023, 2024, 2025], "iso": "PJM", "file": "frontend/data/backcast/runs/2026-06-22-pjm-40-coal-fidelity.js"}, {"id": "2026-06-22-pjm-41-fullstop-override", "label": "pjm 41 fullstop override", "date": "2026-06-22", "shorthand": "pjm-41-fullstop-override", "definition": "pjm_40_coalfidelity: pjm_39 local-band config (verbatim) + the heat-input->MWh proxy for grossLoad-blank coal + the coal-cogen CHP/BTM holdout (Eastman/St Nicholas/John B Rich/...). Measured-anchored, no new flags; 2023 only [merged 2023-25 from parallel per-year solves]", "years": [2023, 2024, 2025], "iso": "PJM", "file": "frontend/data/backcast/runs/2026-06-22-pjm-41-fullstop-override.js"}, {"id": "2026-06-22-pjm-42-campd-nan", "label": "pjm 42 campd nan", "date": "2026-06-22", "shorthand": "pjm-42-campd-nan", "definition": "pjm_37_retiree: pjm_36 refconvex config + within-window retiree CEMS measured-availability cap (retiree_cems_cap=True) \u2014 each retiree plant limited to its measured monthly CAMPD envelope, closing the Homer City phantom-baseload over without tuning to the coal target, 2023 only [merged 2023-25 from parallel per-year solves]", "years": [2023, 2024, 2025], "iso": "PJM", "file": "frontend/data/backcast/runs/2026-06-22-pjm-42-campd-nan.js"}, {"id": "2026-06-22-run145-rtordpa-overlay", "label": "run145 rtordpa overlay", "date": "2026-06-22", "shorthand": "run145-rtordpa-overlay", "definition": "run134 recipe re-solved with measured 2023 AS; load-RRS-from-year=2023; storage-AS-from-year=2025; ecrs-requirement=False", "years": [2023, 2024, 2025], "iso": "ERCOT", "file": "frontend/data/backcast/runs/2026-06-22-run145-rtordpa-overlay.js"}, {"id": "2026-06-22-run146-zonal-gas-basis", "label": "run146 zonal gas basis", "date": "2026-06-22", "shorthand": "run146-zonal-gas-basis", "definition": "run134 recipe re-solved with measured 2023 AS; load-RRS-from-year=2023; storage-AS-from-year=2025; ecrs-requirement=False", "years": [2023, 2024, 2025], "iso": "ERCOT", "file": "frontend/data/backcast/runs/2026-06-22-run146-zonal-gas-basis.js"}, {"id": "2026-06-22-run147-new-outage-baseline", "label": "run147 new outage baseline", "date": "2026-06-22", "shorthand": "run147-new-outage-baseline", "definition": "run134 recipe re-solved with measured 2023 AS; load-RRS-from-year=2023; storage-AS-from-year=2025; ecrs-requirement=False", "years": [2023, 2024, 2025], "iso": "ERCOT", "file": "frontend/data/backcast/runs/2026-06-22-run147-new-outage-baseline.js"}, {"id": "2026-06-22-run147-zonal-gas-ep", "label": "run147 zonal gas ep", "date": "2026-06-22", "shorthand": "run147-zonal-gas-ep", "definition": "run134 recipe re-solved with measured 2023 AS; load-RRS-from-year=2023; storage-AS-from-year=2025; ecrs-requirement=False", "years": [2023, 2024, 2025], "iso": "ERCOT", "file": "frontend/data/backcast/runs/2026-06-22-run147-zonal-gas-ep.js"}, {"id": "2026-06-22-run149-zonal-gas-prb", "label": "run149 zonal gas prb", "date": "2026-06-22", "shorthand": "run149-zonal-gas-prb", "definition": "run134 recipe re-solved with measured 2023 AS; load-RRS-from-year=2023; storage-AS-from-year=2025; ecrs-requirement=False", "years": [2023, 2024, 2025], "iso": "ERCOT", "file": "frontend/data/backcast/runs/2026-06-22-run149-zonal-gas-prb.js"}, {"id": "2026-06-22-run150-stgas-netload-drag", "label": "run150 stgas netload drag", "date": "2026-06-22", "shorthand": "run150-stgas-netload-drag", "definition": "run134 recipe re-solved with measured 2023 AS; load-RRS-from-year=2023; storage-AS-from-year=2025; ecrs-requirement=False", "years": [2023, 2024, 2025], "iso": "ERCOT", "file": "frontend/data/backcast/runs/2026-06-22-run150-stgas-netload-drag.js"}, {"id": "2026-06-23-caiso-20-bidir-intertie", "label": "caiso 20 bidir intertie", "date": "2026-06-23", "shorthand": "caiso-20-bidir-intertie", "definition": "Calibration run from bundle caiso_bidir_intertie.", "years": [2023, 2024, 2025], "iso": "CAISO", "file": "frontend/data/backcast/runs/2026-06-23-caiso-20-bidir-intertie.js"}, {"id": "2026-06-23-caiso-21-bidir-floor", "label": "caiso 21 bidir floor", "date": "2026-06-23", "shorthand": "caiso-21-bidir-floor", "definition": "(PROBE \u2014 rejected, keeper stays caiso-import-cap-floor) Attempt to UNIFY the two 2026-06-23 CAISO threads: the bidir-intertie diurnal-shape fix (single signed WECC flow, both legs at the measured hub) PLUS the keeper's level levers ported onto it \u2014 the per-tranche delivered-cost basis now applied to the bidir import legs (line-loss on the positive hub + OATT wheeling, guarded so a negative hub can't break arbitrage-freeness) and the RA gas-commitment floor 0.80 \u2014 with interchange shaping + negative renewable offers. REGRESSES the keeper on every axis: 2024 neg-price hours 194 (keeper 815, actual ~800), net interchange -17.68 TWh (keeper -30.4, actual -32.4), p10 LMP $33.63 (keeper $1.40), mean $48.8 (keeper ~42, actual 35.8); diurnal corr +0.95 (2023) but only +0.09 (2024) and -0.12 (2025), i.e. the gas floor drags the bidir diurnal win back toward zero. ROOT CAUSE: the gas floor (forces gas online) and the delivery basis (raises import cost) BOTH suppress imports, so on the single-flow bidir node the model badly under-imports and the bidir export leg sells the midday surplus at the POSITIVE hub instead of crashing to negative \u2014 the negative tail the keeper relies on disappears, and the level levers prove ANTAGONISTIC with the bidir representation, not additive. Next: decompose (bidir+floor only / bidir+basis only) to find which lever is bidir-compatible; see results/calibration/NEXT-caiso-roadmap-2026-06-23.md.", "years": [2023, 2024, 2025], "iso": "CAISO", "file": "frontend/data/backcast/runs/2026-06-23-caiso-21-bidir-floor.js"}, {"id": "2026-06-23-caiso-22-bidir-floor", "label": "caiso 22 bidir+floor-only", "date": "2026-06-23", "shorthand": "caiso-22-bidir-floor", "definition": "(PROBE \u2014 rejected, keeper stays caiso-import-cap-floor) Decomposition of the rejected caiso-21 unify: the single signed WECC bidir intertie (both legs at the measured hub) PLUS the RA gas-commitment floor 0.80, with NO per-tranche delivered-cost basis on the import legs (basis reverted in transmission.py inject_caiso_bidir_intertie_prices; the basis is the separate basis-only probe). Isolates whether the FLOOR alone is bidir-compatible. Run: --caiso-bidir-intertie --interchange-shaping --negative-renewable-offers --gas-hub-basis-overlay --priced-interchange --hydro-eia930-monthly --caiso-gas-commitment-floor, 3-yr. RESULT 2024: neg-price hrs 221 (keeper 815, actual ~800), net interchange -22.36 TWh (keeper -30.4, actual -32.4), p10 LMP $32.24 (keeper $1.40), mean $46.81 (keeper ~42, actual 35.8), diurnal corr +0.22. 2023: net -19.41 (actual -28.87), neg 48, mean 77.71, corr +0.95. 2025: net -30.63 (actual -36.16), neg 9, mean 52.01, corr +0.11. VERDICT: does NOT beat the keeper. Dropping the basis recovered some imports/tail vs the unify (2024 net -22.36 vs -17.68, neg 221 vs 194, corr +0.22 vs +0.09) \u2014 so the delivery basis WAS part of the import suppression \u2014 but the model STILL badly under-imports and the negative tail STILL collapses (221 vs keeper 815/actual ~800) and the body stays high. The bidir diurnal corr DOES survive the floor (positive every year: +0.95/+0.22/+0.11, vs the unify's +0.95/+0.09/-0.12), so the floor is diurnal-COMPATIBLE but level-ANTAGONISTIC: the RA gas floor forces gas online and suppresses imports / the negative tail on the single-flow node even with no basis. CONCLUSION: the FLOOR is (also) an import-suppressor on the bidir node \u2014 neither lever fully composes with bidir; basis was a secondary suppressor (confirm via the basis-only probe). Keeper unchanged. See results/calibration/NEXT-caiso-roadmap-2026-06-23.md.", "years": [2023, 2024, 2025], "iso": "CAISO", "file": "frontend/data/backcast/runs/2026-06-23-caiso-22-bidir-floor.js"}, {"id": "2026-06-23-caiso-23-bidir-basis", "label": "caiso 23 bidir+basis-only", "date": "2026-06-23", "shorthand": "caiso-23-bidir-basis", "definition": "(PROBE \u2014 rejected, keeper stays caiso-import-cap-floor) DECOMPOSITION of the rejected caiso-21 unify: isolate the per-tranche delivered-cost BASIS on the bidir-intertie import legs ALONE, with the RA gas-commitment floor explicitly OFF (--no-caiso-gas-commitment-floor; note the flag DEFAULTS ON for CAISO, so omitting it does NOT disable the floor). bidir-intertie + interchange shaping + negative renewable offers + gas-hub-basis overlay, 3-yr. RESULT: basis-only is nearly byte-identical to caiso-21 (basis+floor) on every 2024 axis \u2014 neg-price hours 194 (caiso-21 194; keeper 815; actual ~800), net interchange -19.09 TWh (caiso-21 -17.68; keeper -30.4; actual -32.38), p10 LMP $33.63 (caiso-21 $33.63; keeper $1.40), mean $48.79 (caiso-21 48.8; keeper ~42; actual 35.8), import hours 81.8% vs actual 89.0%; diurnal corr -0.04 (2024), -0.12 (2025), +0.94 (2023 \u2014 static-ladder placeholder, no measured hub so the basis is INACTIVE that year, not informative). 2025 net interchange -25.70 TWh (keeper -38.6; actual -36.16). CONCLUSION: removing the floor barely moved anything, so the DELIVERY BASIS \u2014 not the gas floor \u2014 is the import suppressor on the single-flow bidir node. The multiplicative line-loss markup is too aggressive on the already-capped (8.3 GW) bidir leg: it over-prices imports, collapses the negative tail and net-import magnitude, and drags the diurnal correlation the standalone bidir keeper (caiso-20) flipped POSITIVE back to negative. Next: try wheel-only (additive) delivery or a smaller loss factor on the bidir import legs, grounded as a physical input (rule #12), NOT tuned to the residual; otherwise the diurnal-shape fix (bidir) and the merit-order-restoring basis are mutually exclusive on the capped single-flow node and the keeper stays. See results/calibration/NEXT-caiso-roadmap-2026-06-23.md.", "years": [2023, 2024, 2025], "iso": "CAISO", "file": "frontend/data/backcast/runs/2026-06-23-caiso-23-bidir-basis.js"}, {"id": "2026-06-23-caiso-24-bidir-wheel", "label": "caiso 24 bidir+wheel-only (PROBE)", "date": "2026-06-23", "shorthand": "caiso-24-bidir-wheel", "definition": "PROBE (failed keeper gate). Bidir WECC intertie + RA gas floor 0.80 + ADDITIVE wheel-only delivery basis on the import legs (the per-tranche OATT PTP wheeling charge of CAISO_IMPORT_DELIVERY_BASIS, WITHOUT its multiplicative loss\u00b7max(hub,0) markup). Decompose follow-up to caiso-22 floor-only / caiso-23 basis-only: tests whether the minimal additive wheel restores the rising delivered-import merit order without over-suppressing imports. It does not \u2014 wheel-only lands essentially on basis-only (2024 net -18.66 vs -19.09, neg 194=194, mean 48.34 vs 48.79) and worse than floor-only on both level (net -22.36, neg 221, mean 46.81) and shape (2024 corr +0.14 < floor-only +0.22; 2025 corr -0.07, not positive every year). Confirms the bidir diurnal-shape fix and any merit-order-restoring delivery basis are mutually exclusive by design on the capped 8.3 GW single-flow node; keeper stays until measured WECC hub diurnal prices land (roadmap option B).", "years": [2023, 2024, 2025], "iso": "CAISO", "file": "frontend/data/backcast/runs/2026-06-23-caiso-24-bidir-wheel.js"}, {"id": "2026-06-23-caiso-25-corridor-deliverability", "label": "caiso 25 corridor-deliverability", "date": "2026-06-23", "shorthand": "caiso-25-corridor-deliverability", "definition": "NEW KEEPER. Adds the measured WECC corridor deliverability limit (--caiso-corridor-flow-limit) on top of the per-hub signed legs: each import corridor's import-direction link flow is capped at the per-(month x hour-of-day) p95 measured net import (an ATC proxy from EIA-930 BA-to-BA interchange; one-sided, export keeps the physical TTC). Fixes the diurnal phase residual -- net-import corr flips POSITIVE both scored years (2024 -0.15->+0.08, 2025 -0.36->+0.03), the first per-hub run with the right diurnal sign -- and fixes 2025 over-import (net -41.1->-36.3 TWh vs actual -36.2). Removing the phantom midday thermal import lifts the body to its honest level (mean 2024 +2.6/2025 +4.9) and drops neg-hours (459->346/193->61): the exposed in-state midday over-pricing residual (next phase), NOT a reason to revert (rule #1). 2024 net now under-imports (-28.3) -- the exposed evening import shortfall. P0->P1, commitment off; 2023 = static-ladder hub fallback but corridor cap active (corr +0.97).", "years": [2023, 2024, 2025], "iso": "CAISO", "file": "frontend/data/backcast/runs/2026-06-23-caiso-25-corridor-deliverability.js"}, {"id": "2026-06-23-caiso-import-cap-floor", "label": "caiso import cap floor", "date": "2026-06-23", "shorthand": "caiso-import-cap-floor", "definition": "CAISO keeper: this session's aggregate WECC simultaneous-import cap (8.3 GW) + per-tranche delivered-cost basis over the measured hub MCE, run with the validated RA gas-commitment floor (0.80) and negative renewable offers ON. The floor mechanisms make the model long midday so the price floor crashes to reality: 2024 negative-price hours 815 (~800 actual), LMP p10 $1.40 / min -$20, net interchange -30.4 TWh vs -32.4 actual; 2025 net -38.6 vs -36.2. 2023 over-imports (net -40 vs -29, 99% import hours) because it has no measured WECC hub series (OASIS Jan-Feb aged out) and falls back to the static import ladder. Residual: mean LMP still ~$8 high (evening ramp \u2014 missing AS/reserve co-optimization) and diurnal phase corr negative (separate bidirectional-zone work).", "years": [2023, 2024, 2025], "iso": "CAISO", "file": "frontend/data/backcast/runs/2026-06-23-caiso-import-cap-floor.js"}, {"id": "2026-06-23-caiso-import-simul-cap", "label": "caiso import simul cap", "date": "2026-06-23", "shorthand": "caiso-import-simul-cap", "definition": "(PROBE) Import-isolation diagnostic: aggregate WECC import cap + delivered-cost basis, but with the RA gas-commitment floor and negative renewable offers DISABLED (--no-caiso-gas-commitment-floor --no-negative-renewable-offers) to isolate the import-level effect. Fixes the import quantity (tail -8.3 GW, body median -4.3 GW) but leaves the midday price floor high (only 117 negative hours, LMP min -$5). The keeper that re-enables the floor mechanisms is 2026-06-23-caiso-import-cap-floor.", "years": [2023, 2024, 2025], "iso": "CAISO", "file": "frontend/data/backcast/runs/2026-06-23-caiso-import-simul-cap.js"}, {"id": "2026-06-23-caiso-per-hub-intertie", "label": "caiso per hub intertie", "date": "2026-06-23", "shorthand": "caiso-per-hub-intertie", "definition": "CAISO keeper (structurally-faithful successor to caiso-import-cap-floor): byte-identical config, the ONLY change is the measured WECC intertie parquet now carries the FULL delivered nodal LMP (energy+congestion+loss = MCE+MCC+MCL, GHG excluded) per scheduling point instead of the byte-identical system MCE \u2014 so MALIN (PNW/Mid-C) and PALOVRDE (desert-SW) finally differ (2024 MALIN mean 40.1/313 neg-hrs vs PALOVRDE 33.3/949 neg-hrs). The import injector drops the modeled multiplicative line-loss markup (the measured MCL now carries the real loss) and keeps only the OATT wheel (rules #11/#12). Effect: 2024 mean LMP 42->39.24 toward actual 35.8 (the DIAGNOSIS-caiso-body-overprice midday-floor target improves); 2024 neg-hours 815->873 (actual ~800); 2024 net interchange -30.4->-35.95 TWh (actual -32.4) and 2025 -38.6->-44.18 (actual -36.2) \u2014 over-import GREW because the now-cheaper desert-SW PALOVRDE hub pulls more midday import volume; diurnal phase corr still negative (2024 -0.34). 2023 falls back to the static ladder (OASIS Jan-Feb aged out -> incomplete 8760, unchanged from keeper). Residual / next root cause: the over-import is a discovered downstream issue (import cap / DSW gas coupling), NOT a reason to revert the faithful measured input.", "years": [2023, 2024, 2025], "iso": "CAISO", "file": "frontend/data/backcast/runs/2026-06-23-caiso-per-hub-intertie.js"}, {"id": "2026-06-23-caiso-per-hub-legs", "label": "caiso per-hub legs + solar-shape (PROBE)", "date": "2026-06-23", "shorthand": "caiso-per-hub-legs", "definition": "PROBE \u2014 per-hub signed legs (--caiso-per-hub-intertie) WITH --caiso-import-solar-shape still ON, to test whether the solar-shape proxy still adds anything once the measured per-hub Palo Verde hub is doing the work. Verdict: REDUNDANT. Nearly byte-identical to the per-hub-signed keeper on every axis (2024 mean 43.49 vs 43.82, neg 535 vs 459, net \u221232.65 vs \u221232.39, corr \u22120.17 vs \u22120.15; 2025 mean 44.55 vs 44.86, net \u221241.48 vs \u221241.11, corr \u22120.38 vs \u22120.36). solar-shape was a no-OASIS proxy that collapsed the desert-SW import offer toward \u2212$20 to manufacture the negative midday tail; the measured per-hub hub now prints that tail directly, and on a signed node the \u2212$20 import offer mildly re-inflates the very midday over-import the per-hub legs fix (slightly worse corr, +76 neg-hrs). Confirms dropping solar-shape from the keeper (rule #11: prefer the measured input over the proxy). Not a keeper.", "years": [2023, 2024, 2025], "iso": "CAISO", "file": "frontend/data/backcast/runs/2026-06-23-caiso-per-hub-legs.js"}, {"id": "2026-06-23-caiso-per-hub-signed", "label": "caiso per-hub signed legs", "date": "2026-06-23", "shorthand": "caiso-per-hub-signed", "definition": "CAISO KEEPER candidate \u2014 the structural fix for the over-import (priority 1) the per-hub-intertie keeper surfaced. Splits the single pooled WECC_import node into the two REAL signed corridors \u2014 COI/Path-66 at the Malin hub (WECC_PNW \u2192 NP15) and Path-46/WOR at the Palo Verde hub (WECC_DSW \u2192 SP15) \u2014 each a single net direction per hour priced at its OWN measured intertie hub (--caiso-per-hub-intertie). This unifies the bidir node's per-hub netting (each corridor carries one signed flow, so the cheap Palo Verde midday block reverses to EXPORT instead of flooding the 8.3 GW budget) with the hub-price node's per-hub basis (Malin != Palo Verde), which were thought mutually exclusive. The 8.3 GW simultaneous-import cap is preserved as the WECC_import_simultaneous interface limit re-homed onto the two corridor links. solar-shape DROPPED (the measured per-hub Palo Verde hub already prints the negative midday tail it proxied; redundant on a signed node \u2014 confirmed by the per-hub-legs+solar-shape probe). RESULT vs keeper (2024/2025): net interchange \u221236.04/\u221244.17 \u2192 \u221232.39/\u221241.11 TWh (actual \u221232.38/\u221236.16) \u2014 2024 DEAD-ON, over-import SOLVED; diurnal interchange corr \u22120.35/\u22120.60 \u2192 \u22120.15/\u22120.36 (improved, still negative \u2014 the model still imports midday because the cheap hub invites it; a midday-deliverability mechanism is the remaining priority-2 lever). Mean LMP 39.24/43.03 \u2192 43.82/44.86 and neg-hrs 873/407 \u2192 459/193 REGRESSED \u2014 rule #1: this reveals the keeper's better body was partly an OVER-IMPORT ARTIFACT (cheap midday imports suppressed prices / manufactured negatives); the honest body is higher and the residual is now in-state midday over-pricing (DIAGNOSIS-caiso-body-overprice), NOT import, to fix at root cause. 2023 falls back to the static ladder (OASIS gap). Diagnosis: DIAGNOSIS-caiso-perhub-overimport-diurnal-2026-06-23.md.", "years": [2023, 2024, 2025], "iso": "CAISO", "file": "frontend/data/backcast/runs/2026-06-23-caiso-per-hub-signed.js"}, {"id": "2026-06-23-miso2-importnode", "label": "miso2 importnode", "date": "2026-06-23", "shorthand": "miso2-importnode", "definition": "(PROBE) Adds the forecast-grade reference-price interchange node for MISO (Module M4): PJM/SPP/SERC-South seams, each priced from the neighbor's own gas x heat-rate x EIA-930 load shape (HR 12.3/10.0/12.0; cited interface limits 7.3/4.0/3.0 GW), the LP clearing volume on the spread vs MISO's own LMP. Default-on for MISO via REFERENCE_PRICE_DEFAULT_ISOS; PJM opt-in, ERCOT byte-identical. Also corrected HENRY_HUB_TRAJECTORIES[2025] 2.88->3.52 (actual). Determination NOT-YET: the node is structurally correct and measured-anchored, but MISO's modeled LMP is too low (-6/-14/-13%, pre-existing offer-curve level miss), so fed correctly-priced neighbors the seam EXPORTS MISO's over-cheap energy rather than importing -- net interchange does not reach EIA-930 (model NI +0.1/-7.5/+45.0 vs actual -37.9/-23.1/-19.0 TWh; 2024 imports modestly, 2025 over-exports). Root cause for next pass: MISO price level + the absent firm-hydro (Manitoba) import that a gas-margin seam cannot represent. Mechanism stays in (CLAUDE.md #1); seam not tuned to the net-MWh target (#12).", "years": [2023, 2024, 2025], "iso": "MISO", "file": "frontend/data/backcast/runs/2026-06-23-miso2-importnode.js"}, {"id": "2026-06-23-miso3-reservecoopt", "label": "miso3 reservecoopt", "date": "2026-06-23", "shorthand": "miso3-reservecoopt", "definition": "(PROBE) Adds the in-LP market-wide energy+operating-reserve co-optimization for MISO (scarcity.miso_reserve_coopt_inputs, the MISO analogue of the ERCOT/PJM/NYISO co-opt): requirement = fleet-derived MSSC + 400 MW regulation (~3 GW), VOLL-anchored Reliability-Based Demand Curve to $3,500/MWh, linearised to zero reserve; single footprint-wide reserve family; import node default-on. Determination NOT-YET: the mechanism is structurally correct, live, and sourced (nothing fitted), but FULLY INERT -- reserve_price is exactly $0 in all 26,280 hours, so the energy solution is identical to miso2 (C3a still -9/-17/-14%, net interchange +0.1/-7.5/+45.0 unchanged). The ~3 GW requirement never binds because the perfect-foresight LP holds tens of GW of idle thermal headroom -- the same result the PJM reserve campaign documented. Per CLAUDE.md #1/#11 the requirement was NOT inflated to manufacture scarcity; the structure stays in as the correct baseline. The level miss is carried by market-specific MISO coal offer curves + a firm-hydro (Manitoba) import block (handed off).", "years": [2023, 2024, 2025], "iso": "MISO", "file": "frontend/data/backcast/runs/2026-06-23-miso3-reservecoopt.js"}, {"id": "2026-06-23-miso4-coal-takeorpay", "label": "miso4 coal takeorpay", "date": "2026-06-23", "shorthand": "miso4-coal-takeorpay", "definition": "(NOT-YET; structurally-correct input, fit-neutral) Replaces MISO's uniform ASSUMED coal take-or-pay with the MEASURED EIA-923 Schedule-5 contracted share per plant (coal_takeorpay_MISO.csv) via coal_takeorpay_from_data, wired into split_coal_tranches (MISO is split-fleet, NOT in CAMPD_BINNING_ISOS, so the task's offer_curve_by_group lever is architecturally inert for MISO \u2014 its coal supply curve is t1/t2/t3 from coal_tranche_*_fuel_passthrough). The sunk first tranche now passes 1-contract_share instead of 100%-sunk, mirroring the binned path's campd_tranche_fuel_frac must-run rule. REFUTES the task premise: measured data shows MISO coal is ~97% contract (tonnage-wtd) \u2014 MORE take-or-pay than ERCOT (~71%), not market-bought \u2014 so the deep sunk tranche is correct and coal offers are NOT the C3a/seam lever. Result is near-baseline (coal 180.9/165.5/231.1 vs miso3 181.2/166.1/231.4; meanLMP 29.25/26.15/37.54 vs 29.15/26.12/37.54 still ~9/15/12% low; net interchange +1.4/-6.6/+46.2 vs miso3 +0.1/-7.5/+45.0, marginally MORE export \u2014 vs actual -37.9/-23.1/-19.0). Only the 2 spot-heavy plants (1167 S:100%, 6213 S:47%) bid their first tranche fuller and back down; the 97% contract majority is unchanged. Per CLAUDE.md #1/#12 the measured input stays in even though it doesn't move the residual; the level/import-seam belongs to the firm-hydro (Manitoba) import block (#810) + seam, not the coal curve. ERCOT and the CAMPD-binned ISOs untouched (flag off, byte-identical). energy-reserve-coopt on (inert), import node default-on.", "years": [2023, 2024, 2025], "iso": "MISO", "file": "frontend/data/backcast/runs/2026-06-23-miso4-coal-takeorpay.js"}, {"id": "2026-06-23-miso5-firmhydro", "label": "miso5 firmhydro", "date": "2026-06-23", "shorthand": "miso5-firmhydro", "definition": "(KEEPER structure / NOT-YET metrics) Adds a SEPARATE firm-hydro IMPORT block for Manitoba Hydro (~12.3 TWh/yr = 1,400 MW must-flow firm contracted hydro into MISO-North) \u2014 MISO's single largest real import and the structural reason it is a net importer. Firm hydro has no gas x heat-rate analogue, so it is OUTSIDE the gas-margin reference-price seam (PJM/SPP/SERC): a low near-constant offer ($8/MWh, MISO_MANITOBA_FIRM_IMPORT_*) landed directly in MISO-North and floored as must-flow (inject_miso_firm_imports), modeled on the NYISO firm-imports mechanism. Volume from the Manitoba export-contract band, NOT fitted to the residual (#12). Default-ON for MISO (MISO_FIRM_IMPORT_DEFAULT_ISOS); requires --priced-interchange; ERCOT byte-identical. RESULT: net interchange moves toward EIA-930 actual in all 3 yrs (base +0.1/-7.5/+45.0 -> -4.83/-13.31/+39.13 TWh; actual -37.9/-23.1/-19.0) and mean LMP edges DOWN (28.71/25.49/36.78 -> 28.54/25.27/36.40; actual 31.79/30.80/42.85) \u2014 both exactly as predicted (cheap firm hydro raises imports while displacing marginal gas). Gap only HALF closes: the +12.3 TWh import is partly re-exported by the seam because MISO's LMP sits ~6/14/13% low (the pre-existing miso2 root cause), so a correctly-priced seam stays export-biased. Per #1 the correct structure stays in; closing C2/C3a needs the MISO price-LEVEL fix, not a deeper Manitoba block.", "years": [2023, 2024, 2025], "iso": "MISO", "file": "frontend/data/backcast/runs/2026-06-23-miso5-firmhydro.js"}, {"id": "2026-06-23-miso6-coalclass", "label": "miso6 coalclass", "date": "2026-06-23", "shorthand": "miso6-coalclass", "definition": "Calibration run from bundle miso6_coalclass.", "years": [2023, 2024, 2025], "iso": "MISO", "file": "frontend/data/backcast/runs/2026-06-23-miso6-coalclass.js"}, {"id": "2026-06-23-miso7-zonalload", "label": "miso7 zonalload", "date": "2026-06-23", "shorthand": "miso7-zonalload", "definition": "(PROBE) miso3 reserve-coopt config re-solved on current main with all merged MISO structural work \u2014 per-zone hourly load shapes from EIA-930 sub-BA demand (zones = whole sub-BA/LRZ unions, shares 0.285/0.444/0.271, WI->Central/MO->North), RDT asymmetric links (3000 N->S / 2500 S->N), per-zone wind CF shapes, #812 coal take-or-pay, firm-hydro import. Load-weighted LMP 28.98/25.89/37.11 vs actual 31.79/30.80/42.85 (-8.8/-15.9/-13.4%) \u2014 a few tenths closer than static-share miso3 but the gap persists. Scarcity tail still absent (0h >$200 vs 30/37/88) and zones don't separate (N=C, N<->C link still the 12 GW placeholder). Next levers: a binding N<->C corridor limit and a live scarcity tail, not load-share tuning.", "years": [2023, 2024, 2025], "iso": "MISO", "file": "frontend/data/backcast/runs/2026-06-23-miso7-zonalload.js"}, {"id": "2026-06-23-neiso-26-ps-diag", "label": "neiso 26 ps diag", "date": "2026-06-23", "shorthand": "neiso-26-ps-diag", "definition": "neiso 26 ps-diag (DIAGNOSIS, not a calibration keeper). Byte-faithful re-solve of the neiso-25 fullstop keeper config (--commitment --ct-deployment --hydro-backfill-year 2024 --hydro-eia930-monthly; identical offer curves/overlays/outages, scarcity off, PS adder 0) to surface and root-cause the newly-wired C5b storage-throughput metric. FINDING: NEISO PS under-cycles (2025 model 0.59 vs EIA-930 2.08 TWh, -72%) NOT because of a storage defect but because the energy-only LP collapses the scarcity tail (model >$200 hrs 0/0/14 vs actual 72/43/290; 2025 max $258.98 vs ~$1110). PS round-trip breakeven needs an intraday price ratio >1.25 (RTE 0.80); the model's median daily ratio is 1.15, so PS clears only ~50 days/yr (~20 cycles vs the ~107 needed for 2 TWh) -- energy cap (18.6 GWh) and the $0 adder are non-binding. Step-1 measurement audit: 2023 EIA-930 PS is fully blank and 2024 begins only in Nov (14.8% coverage), so the old +47% '2024 over-cycle' was a 2-month partial scored as a full year; fixed by a coverage gate in eia_loader (storage series <50% reported -> SKIPPED). 2025 under-cycle is a real MODEL MISS handed to the scarcity/winter-gas workstream (daily AGT spot U4 / NEISO reserve scarcity pricing) -- NO storage knob added (claude.md #1/#11/#12). DETERMINATION NOT-YET (C5b storage 2025 + pre-existing C1 CC_REGULAR 2025 +2.15 TWh inherited from neiso-25). See docs/multi-iso/neiso-ps-undercycling-diagnosis-2026-06.md.", "years": [2023, 2024, 2025], "iso": "NEISO", "file": "frontend/data/backcast/runs/2026-06-23-neiso-26-ps-diag.js"}, {"id": "2026-06-23-neiso-27-agt-daily", "label": "neiso 27 agt daily", "date": "2026-06-23", "shorthand": "neiso-27-agt-daily", "definition": "real daily AGT (EIA-narrative prints + Transco shape), retires demand-convexity proxy", "years": [2023, 2024, 2025], "iso": "NEISO", "file": "frontend/data/backcast/runs/2026-06-23-neiso-27-agt-daily.js"}, {"id": "2026-06-23-nyiso-20-daily-coopt", "label": "nyiso 20 daily-coopt-floors", "date": "2026-06-23", "shorthand": "nyiso-20-daily-coopt", "definition": "KEEPER. The daily-Transco-gas keeper lineage (nyiso-16/17) combined for the first time with the three validated fix-#3 structural mechanisms: in-LP LOCATIONAL reserve co-optimization (--energy-reserve-coopt, 7 nested NYCA/East/SENY/NYC reserve families), the Long Island in-city self-supply floor (--nyiso-local-selfsupply, NYISO LMIC/local-reliability rule), and firm HQ/Ontario must-flow imports (--nyiso-firm-imports). Full config: --commitment --gas-monthly-actuals --gas-hub-basis-overlay --gas-hub-basis-daily --priced-interchange --energy-reserve-coopt --nyiso-local-selfsupply --nyiso-firm-imports, all 2023+2024+2025. ROOT-CAUSE of the gating winter/January downstate over-pricing: it is the gas-level artifact (the EIA-923 January receipt cost is winter-storm-inflated), NOT an import-topology bug. The measured daily Transco Z6 NY spot de-smears the within-month cold spike, collapsing the January downstate over-price from ~$98 -> $49 (load-weighted Jan residual +44 -> +5.8) and the over-generating NYC fleet from 40 -> 33.6 TWh (toward EIA-923 29). Canonical gate (verdict price_mean): 2023 +19.9% (keeper nyiso-17 +24.0%), 2024 +2.1% (keeper +7.2%, PASS), 2025 +1.2% (keeper +5.4%, PASS) -- BEATS the keeper on price every year; price_shape 2023 0.212 (keeper 0.251), 2024 0.250 (keeper 0.262). 2023 co2 now PASSES (keeper FAIL +7.7%); 2023 sysvol-gas +3.0% (keeper +5.1%); the keeper's ST_GAS +5.05 TWh fuelmix overshoot is gone. Volume bands held within ~1pp of the documented EIA-930/923 import basis floor (2024/25 gas -11/-9%). REMAINING (bounded, documented): the ~+5-7 $/MWh roughly-uniform downstate body over-price is the import/congestion residual bounded by the gas band (PJM $34 > downstate $29-38, so the deep import tranches cannot clear without breaking the EIA-923 gas band) plus the data-blocked flat-annual Iroquois-Transco summer over-level (fix #1(b), needs a paywalled monthly Iroquois Z2 series -- a winter-concentrated/multiplicative reconstruction is mean-preserving on annual gas and only trades summer for winter, so it is not a clean fix). Dec-2024 -27 and the short 2025 summer tail are the coopt-winter-eligibility follow-on (handoff #2). No fitted adders/haircuts; every input measured and forward-reproducible.", "years": [2023, 2024, 2025], "iso": "NYISO", "file": "frontend/data/backcast/runs/2026-06-23-nyiso-20-daily-coopt.js"}, {"id": "2026-06-23-nyiso-21-family-elig", "label": "nyiso 21 family elig", "date": "2026-06-23", "shorthand": "nyiso-21-family-elig", "definition": "Calibration run from bundle nyiso_21_family_elig.", "years": [2023, 2024, 2025], "iso": "NYISO", "file": "frontend/data/backcast/runs/2026-06-23-nyiso-21-family-elig.js"}, {"id": "2026-06-23-nyiso-22-gas-offer", "label": "nyiso 22 gas offer", "date": "2026-06-23", "shorthand": "nyiso-22-gas-offer", "definition": "Calibration run from bundle nyiso_22_gas_offer.", "years": [2023, 2024, 2025], "iso": "NYISO", "file": "frontend/data/backcast/runs/2026-06-23-nyiso-22-gas-offer.js"}, {"id": "2026-06-23-pjm-43-coalbit-marginal", "label": "pjm 43 coalbit marginal", "date": "2026-06-23", "shorthand": "pjm-43-coalbit-marginal", "definition": "pjm_43_coalbit_marginal: pjm_42_campdfix keeper + bituminous made marginal/price-responsive \u2014 coal_bit_passthrough_floor 0.76->1.0 (full delivered-cost bid on above-must-run tranches) AND coal_bit_dispatchable (bit per-plant CAMPD must-run floor zeroed; all capacity dispatchable, Pmin=0). PRB/lignite/waste keep take-or-pay floors. Spot-coal contract physics, not tuned to the coal/LMP residual, 2023 only [merged 2023-25 from parallel per-year solves]", "years": [2023, 2024, 2025], "iso": "PJM", "file": "frontend/data/backcast/runs/2026-06-23-pjm-43-coalbit-marginal.js"}, {"id": "2026-06-23-pjm-44-coalbit-sigmoid", "label": "pjm 44 coalbit sigmoid", "date": "2026-06-23", "shorthand": "pjm-44-coalbit-sigmoid", "definition": "pjm_44_coalbit_sigmoid_dispatchable: pjm_42_campdfix keeper + coal_bit_dispatchable (bit per-plant must-run floor zeroed, Pmin=0) but the gas-keyed bituminous sigmoid RETAINED (floor 0.76 -> ceil 1.32, mid 3.40), NOT flattened to full cost. Isolates dispatchability with the gas-tied offer intact: cheap gas discounts bit to hold merit, dear gas marks it up to back down, 2023 only [merged 2023-25 from parallel per-year solves]", "years": [2023, 2024, 2025], "iso": "PJM", "file": "frontend/data/backcast/runs/2026-06-23-pjm-44-coalbit-sigmoid.js"}, {"id": "2026-06-23-pjm-46-online-pmin", "label": "pjm 46 online pmin", "date": "2026-06-23", "shorthand": "pjm-46-online-pmin", "definition": "Coal-operations rebuild steps 1-2 on the PJM keeper: coal_takeorpay_from_data (step 1, measured EIA-923 Sch-5 sunk-fuel share) + coal_mustrun_online_pmin (step 2, coal must-run band sized to the measured online-net-MW synchronization Pmin / mustrun_online_pct ~27% cap-wtd, vs the all-hours available-CF mustrun_pct ~44%). Shrinking the cheap sub-cost band moves coal into full-cost tranches so it price-follows: vs the keeper, mean-LMP C3a now PASSes all 3 years (2025 -14.5%->-6.0%, fixing the suppression) and 2023 coal +9.2%->+0.1%; it overshoots to 2024 coal -7.9% / 2025 gas +11.4%, the next root cause (step-3 SRMC tranche + reserve co-opt). Still NOT-YET. Solved 2023-25 (serial per-year solves, merged).", "years": [2023, 2024, 2025], "iso": "PJM", "file": "frontend/data/backcast/runs/2026-06-23-pjm-46-online-pmin.js"}, {"id": "2026-06-23-pjm-47-ps-adder", "label": "pjm 47 ps adder", "date": "2026-06-23", "shorthand": "pjm-47-ps-adder", "definition": "pjm_47_psdiag: pjm_46 online-pmin keeper, PS DISPATCH ADDER RETIRED (PUMPED_STORAGE_DISPATCH_ADDER_BY_ISO PJM $10 -> {}; resolves to 0.0). The $10 had been fitted to a mis-measured EIA-923 PS *net* figure (round-trip loss ~2.6 TWh) read as gross discharge; true discharge throughput is ~7-10 TWh (net*RTE/(1-RTE); PJM Hydro - conventional HY). PS now arbitrages on physical RTE 0.80. All other flags = keeper. 2023 only [merged 2023-25 from parallel per-year solves]", "years": [2023, 2024, 2025], "iso": "PJM", "file": "frontend/data/backcast/runs/2026-06-23-pjm-47-ps-adder.js"}, {"id": "2026-06-23-pjm-48-sync-srmc", "label": "pjm 48 sync srmc", "date": "2026-06-23", "shorthand": "pjm-48-sync-srmc", "definition": "pjm 47 sync-srmc: PJM coal rebuild step 3a (online%-scaled synchronization forcing) on the FULL re-derived thermal tranches. Steps 1+2+3a stacked on the keeper: coal_takeorpay_from_data (measured EIA-923 Sch-5 sunk share) + coal_mustrun_online_pmin (min-load band sized to the measured online-net-MW Pmin) + coal_sync_srmc_tranche (split that band by the contract share into a fuel-free _mustrun floor + a full-SRMC _sync band, both forced ON via min_gen). NEW this run: the forcing is ONLINE%-SCALED via a re-derived plant-level online_frac column (hours any unit synchronized / 8760) \u2014 supercriticals (~1.0) held all 8760 h, two-shifting cyclers forced only in their top-online_frac hours by system load (mirrors the CT must-run load-shaping). The thermal_tranches_PJM.csv was fully re-derived 2023-25, which also corrected the pre-NaN-fix online_hours / committed_pct / mustrun_online_pct for every multi-unit coal+gas plant (CLAUDE.md #12 accurate data). Subbit sigmoid retuned to v3 (ceil 1.65->2.10 / slope 1.4->3.0). RESULTS vs pjm_46 keeper (-7.9/+0.1/+7.5): online%-scaling FIXES the 2023 over-hold (coal +5.5%->-0.1%, all classes in C2 tol); the accurate re-derive (lower committed band) deepens the cheapest-gas 2024 under-run to -9.3% (bit floor VERIFIED saturated: 0.68->0.76->0.90 leaves 2024 bit at -9.4%, so it is NOT an offer-curve lever \u2014 the residual is the step-3b reserve co-opt gap that carries the dear-gas/scarcity volume, memory-blocked per Thread D); 2025 +8.7% (subbit cyclers 876/879 +25% the dominant per-class miss, dear-gas reserve co-opt the lever). Structurally the most complete coal representation (steps 1-3a); residual attributed to the blocked step-3b, not offer-curve fudging. Still NOT-YET pending step-3b. Solved 2023-25 serial, merged.", "years": [2023, 2024, 2025], "iso": "PJM", "file": "frontend/data/backcast/runs/2026-06-23-pjm-48-sync-srmc.js"}, {"id": "2026-06-23-run151-coal-prb-sigmoid", "label": "run151 coal prb sigmoid", "date": "2026-06-23", "shorthand": "run151-coal-prb-sigmoid", "definition": "run134 recipe re-solved with measured 2023 AS; load-RRS-from-year=2023; storage-AS-from-year=2025; ecrs-requirement=False", "years": [2023, 2024, 2025], "iso": "ERCOT", "file": "frontend/data/backcast/runs/2026-06-23-run151-coal-prb-sigmoid.js"}, {"id": "2026-06-23-run152-waha-haircut", "label": "run152 waha haircut", "date": "2026-06-23", "shorthand": "run152-waha-haircut", "definition": "run151 coal-keeper recipe + ERCOT zonal gas with the MEASURED contract haircut (each zone's Waha hub basis scaled by its EIA-923 Schedule-5 gas spot share; West 78% spot). This re-grounds the West/Permian delivered-gas depth on measured data instead of the -0.50 scalar floor, which was DROPPED as non-physical: the contract data shows the CT over-runners buy 100% spot Waha gas, i.e. they genuinely see ~$0 gas, so a floor overstates their fuel (CLAUDE.md #11). The haircut is the honest gas-side correction but small (trims CT_PEAKER from +82.8% to +68.6% in 2024). The remaining CT_PEAKER over-run (C1: 2024 +5.63 TWh, 2025 +4.45 TWh) is an open MODEL MISS for direction 3 (peaker cost/classification): Morgan Creek 3492 is a DFO distillate peaker mispriced on gas, and the GT peakers bid baseload on cheap gas because HR*fuel+VOM understates their low-CF startup/non-fuel cost. LMP MAE 27.9/15.2/11.3 (no regression). See docs/ercot-ct-waha-offer-floor-2026-06.md.", "years": [2023, 2024, 2025], "iso": "ERCOT", "file": "frontend/data/backcast/runs/2026-06-23-run152-waha-haircut.js"}, {"id": "2026-06-23-run153-waha-haircut-perplant", "label": "run153 waha haircut perplant", "date": "2026-06-23", "shorthand": "run153-waha-haircut-perplant", "definition": "run152 with the Waha contract haircut made PER-PLANT instead of zone-average: each gas unit's hub basis is scaled by ITS OWN EIA-923 spot share, so 100%-spot units (Permian Basin, Laredo) keep the full discount while a 100%-contract unit in the same zone (Ector County, share 0.0) loses it entirely. More physically faithful than the zone mean AND a better fit every year (CLAUDE.md #11/#12): CT_PEAKER 2023 -17.6% (was -25.9%), 2024 +48.7% (was +68.6%), 2025 +62.7% (was +66.8%). 358/1124 gas units haircut (mean share 0.51). LMP MAE 27.8/15.2/11.3 (no regression); C2 gas/coal family, C4 dispatch, C5a CO2 pass. The remaining CT_PEAKER over-run (2024 +4.0 TWh) is the open direction-3 MODEL MISS (the 100%-spot Permian peakers genuinely see cheap Waha gas, so the fix is peaker economics/classification, not gas price). The -0.50 floor is NOT used (dropped as non-physical). See docs/ercot-ct-waha-offer-floor-2026-06.md.", "years": [2023, 2024, 2025], "iso": "ERCOT", "file": "frontend/data/backcast/runs/2026-06-23-run153-waha-haircut-perplant.js"}, {"id": "2026-06-23-run154-netload-gas-laredo", "label": "run154 netload gas laredo", "date": "2026-06-23", "shorthand": "run154-netload-gas-laredo", "definition": "run134 recipe re-solved with measured 2023 AS; load-RRS-from-year=2023; storage-AS-from-year=2025; ecrs-requirement=False", "years": [2023, 2024, 2025], "iso": "ERCOT", "file": "frontend/data/backcast/runs/2026-06-23-run154-netload-gas-laredo.js"}, {"id": "2026-06-24-caiso-cc-econ-10", "label": "caiso 26 cc-econ-cut (PROBE)", "date": "2026-06-24", "shorthand": "caiso-cc-econ-10", "definition": "PROBE (rejected) \u2014 Task A: CC_REGULAR+CC_CHP econ_low/econ_high -0.10 to lower the in-state midday body off the caiso-25 corridor keeper. REJECTED: breaks the won diurnal structure (net-import corr flips negative both scored years, 2024 +0.08->-0.03, 2025 +0.03->-0.08) and under-imports (2024 net -28.34->-24.70, below the -28 floor) \u2014 cheaper CC displaces imports in the midday/shoulder hours the corridor cap fixed. Also non-specific (lowers midday/evening/overnight ~uniformly, pulls the matched 2023 evening under actual) and never recovers the negative tail (neg-hrs unchanged 271/24). Confirms residual #2 is structural (model short midday after phantom imports correctly removed), not an offer-curve level. Keeper unchanged. See DIAGNOSIS-caiso-cc-offer-midday-2026-06-24.md.", "years": [2023, 2024, 2025], "iso": "CAISO", "file": "frontend/data/backcast/runs/2026-06-24-caiso-cc-econ-10.js"}, {"id": "2026-06-24-caiso-perhub-shaping-diag", "label": "caiso perhub-shaping diag (PROBE)", "date": "2026-06-24", "shorthand": "caiso-perhub-shaping-diag", "definition": "(PROBE) Keeper config + --caiso-per-hub-intertie + --interchange-shaping. Tests the grounded import-volume lever (measured EIA-930 availability envelope). Fixes import HOURS (95.9% vs 85.9% actual) and diurnal shape, but OVERCORRECTS volume: net imports under-shoot every year (21.2/24.7/31.7 vs actual 28.9/32.4/36.2 TWh) and gas over-burns vs EIA-923. Not a keeper; the correct fix is per-hub SIGNED legs (see HANDOFF-caiso-import-volume-and-2023-data-2026-06-24). 2023 uses the static-ladder fallback for hub LMP (OASIS data aged out), shaped only by the EIA-930 envelope.", "years": [2023, 2024, 2025], "iso": "CAISO", "file": "frontend/data/backcast/runs/2026-06-24-caiso-perhub-shaping-diag.js"}, {"id": "2026-06-24-miso8-campd-binning", "label": "miso8 campd-binning (pre-tz ablation)", "date": "2026-06-24", "shorthand": "miso8-campd-binning", "definition": "ABLATION (binning-only, pre-timezone) \u2014 SUPERSEDED as keeper by `miso8 tz-localclock` (PR #853), which adds the MISO UTC-vs-local clock fix on top of this same binning. Keep as the isolation point for the per-plant binning effect alone. CLOCK CAVEAT: this bundle was solved on the old UTC demand clock, so its diurnal/shape comparison against main's now-local-clock benchmark shows a ~5-6h phantom phase error \u2014 that is the clock artifact the tz fix removed, NOT a model result; only the year-mean LMP level (clock-independent) is a valid read here. STRUCTURAL change isolated: MISO moved off the legacy equal-width aggregate_fleet path onto per-plant CAMPD tranche binning (now in CAMPD_BINNING_ISOS) \u2014 one LP unit per plant with must-run/committed/peaking tranches from the new thermal_tranches_MISO.csv (44 coal plants, measured online Pmin ~20-30% nameplate; CC per-plant committed bands), plus the all-ISO biomass measured must-run change (#844). Coal now holds its overnight/morning take-or-pay floor instead of cycling to zero. System LMP level: model 31.49/27.99/39.34 vs actual ~31.79/30.80/42.85 ($/MWh; -0.9%/-9.1%/-8.2% vs legacy miso7's -8.8%/-15.9%/-13.4%) \u2014 C3a mean-LMP PASS. NOT-YET: governance unattested + open MODEL MISSes that are NOT the binning \u2014 absent scarcity tail (0h >$200 vs 30/37/88) and the import/export-node seam (2025 sign-flips to net export, driving 2025 coal +23%); zones still don't separate (N=C, 12 GW N<->C placeholder). PRB passthrough still flat (no MISO COAL_SIGMOID_DEFAULTS entry) \u2014 a separate offer-curve lever; a cheap-gas PRB discount would push the already-low LMP further from actual, so not the next fix.", "years": [2023, 2024, 2025], "iso": "MISO", "file": "frontend/data/backcast/runs/2026-06-24-miso8-campd-binning.js"}, {"id": "2026-06-24-miso8-tz-localclock", "label": "miso8 tz localclock", "date": "2026-06-24", "shorthand": "miso8-tz-localclock", "definition": "miso8 tz-localclock: fixes a confirmed UTC-vs-local clock misalignment AND picks up per-plant CAMPD tranche binning (MISO added to CAMPD_BINNING_ISOS, PR #843). MISO renewable CF was on local time but both demand sources were UTC (~5h CDT / ~6h CST ahead), pairing midday solar / nocturnal wind against trough demand and cycling coal PRB + CC down across 03:00-13:00 where CAMPD shows them hot. Fix: system demand re-sourced from the EIA-930 MISO hourly frame Demand column (was the UTC demand-profiles parquet; identical 641 TWh / peak, only the clock moves), and the sub-BA zonal shares mapped UTC->local via that same frame, so demand and renewable CF share one local wall clock (offset derived from the clock, not the fit; rule #12). RESULT: summer coal diurnal now bottoms ~local 05:00 and ramps to an 18:00 peak, tracking the CAMPD ramp (bottom 04:00 / peak 19:00) at 0.995 shape correlation vs the prior phantom-surplus midday cliff; C3a mean-LMP and C3b shape PASS. Same miso7/miso3 reference-coopt config (reference-price interface + priced interchange + firm hydro imports, all default-on). NOT-YET overall: C1/C2 still under on gas/coal volume (CT_PEAKER ~-26 TWh prices out) and the scarcity tail (C3c) is absent \u2014 both pre-existing MISO misses, not tz-related.", "years": [2023, 2024, 2025], "iso": "MISO", "file": "frontend/data/backcast/runs/2026-06-24-miso8-tz-localclock.js"}, {"id": "2026-06-24-neiso-28-hydro-codramp", "label": "neiso 28 hydro codramp", "date": "2026-06-24", "shorthand": "neiso-28-hydro-codramp", "definition": "neiso-27 + EIA-930 hydro repin + storage vintage ramp + renewable/storage retirement ramp", "years": [2023, 2024, 2025], "iso": "NEISO", "file": "frontend/data/backcast/runs/2026-06-24-neiso-28-hydro-codramp.js"}, {"id": "2026-06-24-neiso-29-biomass-mustrun", "label": "neiso 29 biomass mustrun", "date": "2026-06-24", "shorthand": "neiso-29-biomass-mustrun", "definition": "neiso-28 + biomass measured must-run injection + like-for-like total comparison", "years": [2023, 2024, 2025], "iso": "NEISO", "file": "frontend/data/backcast/runs/2026-06-24-neiso-29-biomass-mustrun.js"}, {"id": "2026-06-24-neiso-30-other-carry", "label": "neiso 30 other carry", "date": "2026-06-24", "shorthand": "neiso-30-other-carry", "definition": "(DIAGNOSTIC; keeper stays neiso-29) neiso-29 + OTHER residual class vintage-carry (2025 OTHER 2.61->2.78 TWh, measured EIA-923 like biomass): small correct fix (C1 +3.64->+3.56, C2 +3.0%->+2.5%). Solved on current main, so it also surfaces a8b0e55 (CC nameplate ~75%->92%) dropping NEISO prices 13-18% into under-prediction (C3a -15.9/-14.0/-8.1%) and storage -76% -- a SEPARATE NEISO CC-availability item, not the biomass/OTHER work.", "years": [2023, 2024, 2025], "iso": "NEISO", "file": "frontend/data/backcast/runs/2026-06-24-neiso-30-other-carry.js"}, {"id": "2026-06-24-nyiso-23-li-oil", "label": "nyiso 23 li oil", "date": "2026-06-24", "shorthand": "nyiso-23-li-oil", "definition": "Calibration run from bundle nyiso_23_li_oil_fix.", "years": [2023, 2024, 2025], "iso": "NYISO", "file": "frontend/data/backcast/runs/2026-06-24-nyiso-23-li-oil.js"}, {"id": "2026-06-24-nyiso-24-import-recon", "label": "nyiso 24 import recon", "date": "2026-06-24", "shorthand": "nyiso-24-import-recon", "definition": "Calibration run from bundle nyiso_24_import_recon.", "years": [2023, 2024, 2025], "iso": "NYISO", "file": "frontend/data/backcast/runs/2026-06-24-nyiso-24-import-recon.js"}, {"id": "2026-06-24-nyiso-25-scarcity-merit", "label": "nyiso 25 rcpf-steep (PROBE)", "date": "2026-06-24", "shorthand": "nyiso-25-scarcity-merit", "definition": "PROBE (rejected, not a keeper). Tests the bucket-A #1 scarcity hypothesis: steepen the NYISO locational RCPF reserve demand curves from the linear-ramp-to-zero stand-in to the published top-25%-span shape (critical_mw = 0.75 x requirement; FERC ER21-502 sets the NYCA 30-min $750 max at 1,965 = 0.75 x 2,620), plus the Ravenswood steam-HR correction. Finding: the steeper published curve DEEPENS the downstate tail faithfully (NYC max $138->$890, 2023 14h >$300) but does NOT add C3c tail HOURS (2024 0h, 2025 12h, unchanged) because the tail COUNT is incidence-gated by the model\u2019s too-loose downstate reserve headroom (idle NYC peakers provide ample reserve; perfect-foresight import over-service backs down downstate gas), not by the demand-curve slope. The deeper few-hour spikes push C3a mean LMP to +12% (over the +-8% band) for no C3c gain. CONCLUSION: the RCPF demand-curve SHAPE is not the C3c lever; the lever is downstate reserve INCIDENCE (locational headroom / import discipline) \u2014 the documented next structural step, out of scope as it would touch the nyiso-24 import reconciliation. The curve steepening is therefore NOT carried into the keeper (nyiso 25 steam-merit), which retains only the Ravenswood merit-order fix.", "years": [2023, 2024, 2025], "iso": "NYISO", "file": "frontend/data/backcast/runs/2026-06-24-nyiso-25-scarcity-merit.js"}, {"id": "2026-06-24-nyiso-25-steam-merit", "label": "nyiso 25 steam merit", "date": "2026-06-24", "shorthand": "nyiso-25-steam-merit", "definition": "KEEPER. Re-solves the nyiso-24 import-reconciliation keeper config (byte-identical flags) with ONE model-side data correction (data.fleet.MIXED_FACILITY_STEAM_HR): the Ravenswood (plant 2500, NYC) mixed CC+ST facility had its ~1.7 GW steam units inheriting the 8.8 MMBtu/MWh plant-blended heat rate (the efficient combined cycle\u2019s efficiency leaking into the steam row), so the big NYC steam unit cleared AHEAD of idle NYC combined cycle on merit (the 2023 CC_REGULAR -4.06 / ST_GAS +3.55 TWh inversion). Recovered the steam units\u2019 own HR (9.5) by backing the CC (~7.5) out of the 8.8 generation-weighted blend; restores the physically-correct merit order (CC ahead of steam). CC_REGULAR improves EVERY year (2023 -4.06->-3.47, 2024 -3.21->-2.61, 2025 -1.20->-0.6) and the 2023 ST_GAS over-run shrinks (+3.55->+2.76). A rule-#11 measured-data correction, forward-reproducible, not fitted to a residual. Tradeoff (kept per rule #1): C3a 2025 mean LMP +9.3% (just over +-8%) because import-constrained NYC over-relies on Ravenswood steam as marginal \u2014 a discovered symptom of the NYC import-incidence root cause (out of scope), not a reason to revert the correct HR. The RCPF scarcity tail (C3c) is unchanged: it is incidence-gated, not curve-gated (see the nyiso 25 rcpf-steep PROBE). Determination NOT-YET (the hard EIA-930/923 gas basis floor, ledgered).", "years": [2023, 2024, 2025], "iso": "NYISO", "file": "frontend/data/backcast/runs/2026-06-24-nyiso-25-steam-merit.js"}, {"id": "2026-06-24-pjm-49-seam-hr", "label": "pjm 49 seam hr", "date": "2026-06-24", "shorthand": "pjm-49-seam-hr", "definition": "(DIAGNOSTIC) pjm 48 coal keeper + two grounded reference-price seam corrections. (1) hr_by_year: MISO/NYISO priced per backcast year from their OWN measured realized LMP (MISO 12.38/13.92/12.03, NYISO 9.66/12.92/14.67), replacing the single 3-year-mean marginal_heat_rate that over-priced the dear-gas year. (2) Carolinas HR 13.5->11.6, reconciled to its OWN documented ~$30/MWh SERC-bilateral basis ($30/$2.54/1.02; 13.5 gave $34, +14% over, and was the highest HR of any neighbor for a cheaper region PJM net-imports from). Both rule #12 (measured/reconciled-documented > compensating estimate); forecast byte-identical. RESULT: net interchange 2023 +22.5 / 2024 +31.2 / 2025 +48.5 vs target +40/+32.7/+18 (MAE 16.5 vs 15.7 baseline); 2024 now near-perfect, Carolinas direction corrected (2024 -4.8 vs measured -6.4), gas improves 2023 (+1.9 vs +5.6) and 2025 (+10.4 vs +12.1). The MAE is marginally worse only because the fixes remove the compensating Carolinas over-export + NYISO-2023 over-price that were MASKING the real bug, now cleanly isolated: the model UNDER-clears export to MISO/NYISO (2023 MISO +17.6 vs measured +35.3, NYISO +4.3 vs +18.5) -- the $2 hurdle exceeds the ~$1.5 mean PJM-MISO spread, so the energy-spread seam can't reproduce PJM's large firm exports. Next: (1) MISO/NYISO under-export (hurdle/convex-slide), (2) add the TVA/LGEE import seam (~-8 TWh/yr), (3) anchor NYISO to the PJM-NY border not the NYC-inflated system avg, (4) 2025 EIA-930 sits ~15 TWh below PJM's per-tie sum -- a measured-source basis gap. pjm 48 stays the PJM keeper. Merged 2023-25 from parallel per-year solves. See bundle SUMMARY-seam-structure.md.", "years": [2023, 2024, 2025], "iso": "PJM", "file": "frontend/data/backcast/runs/2026-06-24-pjm-49-seam-hr.js"}, {"id": "2026-06-25-caiso-26-gas-commodity", "label": "caiso 26 gas-commodity-verify", "date": "2026-06-25", "shorthand": "caiso-26-gas-commodity", "definition": "VERIFICATION RUN (not a new keeper). 3-year HEAD reproduction of the keeper config (--gas-hub-basis-overlay + --caiso-import-gas-coupling + --caiso-per-hub-intertie + --caiso-corridor-flow-limit) confirming both requested levers are ALREADY implemented and active: (PRIMARY) commodity-spot gas / lever B reprices every gas unit at Henry-Hub-month + measured SoCal/PG&E citygate basis (data IN REPO, gas_basis_by_iso_month.csv; gas 2024 F923 $4.31 -> citygate $3.38; 1139 units, 12/12 months) and drops the F923 pipeline reservation as sunk; (SECONDARY) per-hub signed legs (two corridors Malin/COI->NP15, PaloVerde/Path-46->SP15, per-hub basis + netting + corridor deliverability cap). Determination: the body stays +25-41% over actuals (2024 system p50 $45.77 vs RT median $33.99) because even at the commodity spot the gas-CC SRMC floor (HR~7.3 x $3.38 + CARB ~$13 ~= $42) STRUCTURALLY EXCEEDS the actual median -- re-pricing gas cannot reach $34 (confirms 2026-06-19 lever-B diagnosis pt #4). Gas vol: 2023 77.9~=76.0 ok; 2024 77.6 vs 67.7 over, but that is a +7 TWh over-gen drift (under-import + solar-over), not a lever-B artifact. Net interchange -29.7/-28.9/-39.7 vs -28.9/-32.4/-36.2. Marginally lower body than the stale-sha keeper (2024 NP15 47.4->46.0), no regression -> keeper 2026-06-23-caiso-25-corridor-deliverability stands. See results/calibration/DETERMINATION-caiso-gas-commodity-and-perhub-2026-06-25.md.", "years": [2023, 2024, 2025], "iso": "CAISO", "file": "frontend/data/backcast/runs/2026-06-25-caiso-26-gas-commodity.js"}, {"id": "2026-06-25-miso9-pjm-seam-hranchor", "label": "miso9 pjm seam hranchor", "date": "2026-06-25", "shorthand": "miso9-pjm-seam-hranchor", "definition": "miso9 pjm-seam-hranchor: first MISO keeper on current main (picks up the ISO-generic CC-tranche PRs #846/#857, which lift MISO gas to ~208 TWh in 2024 vs stale miso8's 160) PLUS a new structural seam lever \u2014 a per-year MEASURED marginal-heat-rate anchor on MISO's PJM NeighborInterface (hr_by_year={2023:11.2, 2024:13.49, 2025:12.18}), derived by derive_neighbor_hr_by_year.py from PJM's own realized RT LMP / Henry Hub (the same method PJM's own seam already uses), replacing the flat 3-year mean 12.3. The flat mean under-priced the PJM hub in dear-gas 2024 (measured 13.49), driving the largest MISO seam to over-import. ISOLATED 2024 test (vs current-main baseline, only the seam constant changed): net over-import 60.3->48.3 TWh, net-interchange duration RMSE 4592->3259 MW, import-hours 97.7->92.8% (actual 90.9%), with the freed load picked up by domestic coal (+6) and gas (+6) toward actual \u2014 every metric moved toward actual. Measured price-formation input (rule #12), derived blind to MISO's own flow (rule #11); kept on faithfulness grounds even where a single year's fit worsens (rule #1). PASS C3a mean-LMP (30.8/28.9/39.5 vs ~30.8/30.8/42.9), C3b shape, C4 dispatch-r, C6 governance. OPEN MISSES (documented, not masked \u2014 next levers): (1) systematic net over-import persists all years (2023 63.6 vs 37.9; SPP/South seams still flat, un-anchored + import-node level over-serves); (2) 2025 net-interchange sign-flip persists (model +7.5 net export vs actual -19) driven by the 2025 coal over-run (235 vs 192) making MISO long \u2014 a coal-offer/merit root cause the 2025 PJM anchor (12.18 ~ flat) doesn't touch (C2 2025 gas -20.6%/coal +22.4%); (3) CT_PEAKER already runs at the ~4% actual reserve level on current main (2.97 TWh / 3.9% CF in 2024) \u2014 the task's stale 'CT prices out ~0%' miss is RESOLVED by the CC-tranche PRs; --ct-mustrun-per-plant was tested and REJECTED for MISO (over-forces CT to 18.8 TWh because ct_mustrun_floor_mwh_by_plant sweeps combined-cycle CT-prime-mover EIA-923 net-gen into the CT_PEAKER floor \u2014 a rule #1 trap that nudges the import metric toward actual via an unreal CT over-dispatch); (4) scarcity tail absent C3c (0h vs 30/37/88 >$200); (5) C5a CO2 -20% (tracks the domestic under-generation from over-import). Solved per-year (2023/2024/2025 separate processes, merged into one bundle) because a 3-year per-plant MISO LP OOMs at 16 GB on a 15 GB box; MISO backcast has no cross-year dependency, so per-year == combined.", "years": [2023, 2024, 2025], "iso": "MISO", "file": "frontend/data/backcast/runs/2026-06-25-miso9-pjm-seam-hranchor.js"}, {"id": "2026-06-25-neiso-31-cc-minload", "label": "neiso 31 cc minload", "date": "2026-06-25", "shorthand": "neiso-31-cc-minload", "definition": "NEISO CC_REGULAR committed min-load tranche re-anchored 0.92->1.27 (=econ_high) per measured CAMPD min-stable-load HR (1.30x avg vs full-load 0.93x); min-load priced at-or-above full-load SRMC, removes wall-masked cheap min-load block. a8b0e55 kept ON. vs neiso-30.", "years": [2023, 2024, 2025], "iso": "NEISO", "file": "frontend/data/backcast/runs/2026-06-25-neiso-31-cc-minload.js"}, {"id": "2026-06-25-nyiso-26-cc-nameplate", "label": "nyiso 26 cc nameplate", "date": "2026-06-25", "shorthand": "nyiso-26-cc-nameplate", "definition": "Calibration run from bundle nyiso_26_cc-nameplate.", "years": [2023, 2024, 2025], "iso": "NYISO", "file": "frontend/data/backcast/runs/2026-06-25-nyiso-26-cc-nameplate.js"}, {"id": "2026-06-25-nyiso-27-cc-offer", "label": "nyiso 27 cc offer", "date": "2026-06-25", "shorthand": "nyiso-27-cc-offer", "definition": "Calibration run from bundle nyiso_27_cc-offer.", "years": [2023, 2024, 2025], "iso": "NYISO", "file": "frontend/data/backcast/runs/2026-06-25-nyiso-27-cc-offer.js"}, {"id": "2026-06-25-run155a-netload-gas-storage", "label": "run155a netload gas storage", "date": "2026-06-25", "shorthand": "run155a-netload-gas-storage", "definition": "run134 recipe re-solved with measured 2023 AS; load-RRS-from-year=2023; storage-AS-from-year=2024; ecrs-requirement=False; battery-adder=10.0", "years": [2023, 2024, 2025], "iso": "ERCOT", "file": "frontend/data/backcast/runs/2026-06-25-run155a-netload-gas-storage.js"}, {"id": "2026-06-25-run155b-netload-gas-adder0", "label": "run155b netload gas adder0", "date": "2026-06-25", "shorthand": "run155b-netload-gas-adder0", "definition": "run134 recipe re-solved with measured 2023 AS; load-RRS-from-year=2023; storage-AS-from-year=2025; ecrs-requirement=False; battery-adder=0.0", "years": [2023, 2024, 2025], "iso": "ERCOT", "file": "frontend/data/backcast/runs/2026-06-25-run155b-netload-gas-adder0.js"}, {"id": "2026-06-25-run155c-netload-gas-storage", "label": "run155c netload gas storage", "date": "2026-06-25", "shorthand": "run155c-netload-gas-storage", "definition": "run134 recipe re-solved with measured 2023 AS; load-RRS-from-year=2023; storage-AS-from-year=2024; ecrs-requirement=False; battery-adder=0.0", "years": [2023, 2024, 2025], "iso": "ERCOT", "file": "frontend/data/backcast/runs/2026-06-25-run155c-netload-gas-storage.js"}, {"id": "2026-06-25-run156-ecrs-requirement-probe", "label": "run156 ecrs requirement probe", "date": "2026-06-25", "shorthand": "run156-ecrs-requirement-probe", "definition": "(PROBE \u2014 REJECTED) run155a keeper + measured ECRS reserve requirement ON from 2023 (ercot_ecrs_requirement). Tested the May-2024 under-price hypothesis. Verdict: rejected. The flat +~2 GW ECRS reserve add does NOT fix May 2024 (load-wtd $23.6->$24.0, target $38-45) because May is not physically reserve-thin in the model \u2014 the co-opt ORDC steps only bite in genuinely-thin hours, so the add OVERSHOOTS Aug 2024 ($30.4->$53.5 vs actual 36) and catastrophically over-fires 2023-H2 (annual $48->$128, Aug $147->$598; no storage-AS credit in 2023). Battery throughput held (2024 0.78 TWh). Confirms the May miss is DAM ancillary-service co-optimized scarcity (hypothesis 4), not RT energy/reserve thinness. Keeper remains run154/run155a.", "years": [2023, 2024, 2025], "iso": "ERCOT", "file": "frontend/data/backcast/runs/2026-06-25-run156-ecrs-requirement-probe.js"}];